tap_action.javascript:
[[[
  // HA's root element owns the hass-action listener; a pinned capsule can live outside its tree.
  const root = document.querySelector('home-assistant') || this;
  root.dispatchEvent(new CustomEvent('hass-action', {
    bubbles: true, composed: true,
    detail: { config: { tap_action: { action: 'assist' } }, action: 'tap' },
  }));
]]]

