hemma_camera_alert_helper.value:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  if (typeof window.hemmaCameraAlert !== 'function') {
    window.hemmaCameraAlert = function (hass, states, cams, windowMinutes) {
      const reg = (hass && hass.entities) || {};
      const devs = {};
      cams.forEach(function (id) {
        const d = reg[id] && reg[id].device_id;
        if (d) devs[d] = true;
      });
      const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
      const now = Date.now();
      states['sensor.time'];
      let ding = false, motion = false;
      Object.keys(reg).forEach(function (id) {
        if (id.indexOf('event.') !== 0) return;
        if (!devs[reg[id].device_id]) return;
        const t = Date.parse(states[id] && states[id].state);
        if (!isFinite(t) || now - t > span) return;
        if (/ding|doorbell|button/.test(id)) ding = true;
        else if (/motion/.test(id)) motion = true;
      });
      return ding ? T('cameras.doorbell', 'Doorbell') : motion ? T('cameras.motion_detected', 'Motion Detected') : '';
    };
  }
  return true;
]]]

card.display:
[[[
  const v = variables?.enabled;
  if (v === undefined || v === null) return 'inline-grid';
  if (typeof v === 'boolean') return v ? 'inline-grid' : 'none';
  if (typeof v === 'number') return v !== 0 ? 'inline-grid' : 'none';
  const s = String(v).trim().toLowerCase();
  if (['false','0','no','off','disabled'].includes(s)) return 'none';
  return 'inline-grid';
]]]

card.--hemma-badge-enter-delay:
[[[
  const step = Number(variables?.enter_step ?? 22);
  let i = 0;
  try {
    const sibs = this.parentElement?.children;
    if (sibs && sibs.length > 1) {
      for (const el of sibs) {
        if (el === this) break;
        if (el.localName !== this.localName) continue;
        const c = el.shadowRoot && el.shadowRoot.querySelector('ha-card');
        if (c && c.style.display === 'none') continue;
        i++;
      }
    }
  } catch (e) {}
  return i > 0 ? (i * step) + 'ms' : 'inherit';
]]]

hemma_badge_base.extra_styles:
:host{
  --badge-sub-opacity: var(--hemma-badge-sub-opacity, .80);
  --badge-after-z:  2;
  --badge-before-z: 3;
  --hemma-badge-hover-shadow: none;

  /* Sub-badge entrance */
  --hemma-badge-enter-t: var(--hemma-row-fade, 1);
  --hemma-badge-enter-p: calc(1 - var(--hemma-badge-enter-t));
  --hemma-badge-enter-lift: -22px;
  --hemma-badge-enter-depth: 0.24;
  --hemma-badge-enter-origin: 50% -45%;
  --hemma-badge-enter-dur: calc(0.30s + var(--hemma-badge-enter-t) * 0.12s);
  --hemma-badge-enter-fade: calc(0.18s + var(--hemma-badge-enter-t) * 0.04s);
  --hemma-badge-enter-squash: 0.08;
  --hemma-badge-enter-transform:
    translateX(calc(var(--hemma-badge-enter-p) * var(--hemma-badge-converge-x, 0px)))
    translateY(calc(var(--hemma-badge-enter-p) * var(--hemma-badge-enter-lift)))
    scaleX(calc(1 - var(--hemma-badge-enter-p) *
      (var(--hemma-badge-enter-depth) - var(--hemma-badge-enter-squash))))
    scaleY(calc(1 - var(--hemma-badge-enter-p) *
      (var(--hemma-badge-enter-depth) + var(--hemma-badge-enter-squash))));
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  :host {
    --hemma-badge-enter-lift: 0px !important;
    --hemma-badge-enter-depth: 0 !important;
    --hemma-badge-enter-squash: 0 !important;
