hemma_entity.hidden:
[[[
  const off = (v) => v === false || v === 'false' || v === 0 || v === '0';
  if (off(variables?.enabled)) return true;
  if (String(variables?.show_when ?? 'always') !== 'active') return false;
  const idle = variables?.idle;
  return idle === true || idle === 'true' || idle === 1 || idle === '1';
]]]

hemma_entity.extra_styles:
/* Diagonal specular hairline */
ha-card::before{
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  padding: 1px;
  box-sizing: border-box;
  opacity: var(--hemma-active-overlay-opacity, 0);
  background: linear-gradient(
    to bottom right,
    var(--hemma-card-specular-start, transparent) 0%,
    var(--hemma-card-specular-mid, transparent) 45%,
    var(--hemma-card-specular-mid, transparent) 55%,
    var(--hemma-card-specular-end, transparent) 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
}

#battery{
  opacity: 0;
  transform: scale(.92);
  transition: opacity .8s ease, transform .3s ease;
  will-change: opacity, transform;
}

@media (hover: hover) and (pointer: fine){
  :host(:hover) #battery,
  :host(:focus-within) #battery{
    opacity: .6;
    transform: scale(1);
  }
}

@media (hover: none) and (pointer: coarse){
  #battery{ opacity: 0; }
}

/* Progress */
#progress {
  background: none !important;
  mask: none !important;
  -webkit-mask: none !important;
  overflow: visible;
}

#progress svg {
  position: relative;
  z-index: 1;
}

#progress svg .hemma-progress-glyph {
  fill: var(--hemma-progress-arc-color, var(--hemma-color-teal, #00c3d0));
  stroke: var(--hemma-progress-arc-color, var(--hemma-color-teal, #00c3d0));
}

#progress svg .hemma-progress-track {
  stroke: var(--hemma-progress-track-color, rgba(0,0,0,0.12));
}

#progress svg .hemma-progress-arc {
  stroke: var(--hemma-progress-arc-color, rgba(255,255,255,0.5));
  stroke-opacity: var(--hemma-progress-arc-opacity, 1);
  stroke-dashoffset: calc(87.965px - var(--hemma-progress-pct, 0) * 0.87965px);
  transition: stroke-dashoffset 0.8s linear;
}

/* Toggle tracks the tile unit, like the icon circle, so it stays proportional to the
   card. A fraction of the height, never height/200px: dividing a length by a length
   is CSS Values 4 and Firefox drops the whole declaration. On :host so it also
   reaches cards whose root element the ha-card selector does not match. */
:host {
  --hemma-toggle-width: 44px;
  --hemma-toggle-height: 25px;
}

ha-card {
  --hemma-height-mq: var(--hemma-entity-height-current, var(--hemma-entity-height-desktop, 200px));
  --hemma-box-shadow-mq: var(--hemma-tile-glass-rim-desktop, var(--hemma-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10)));
  /* Sized off the icon circle: two balanced circles in opposite corners. Ratio, not a
     literal, so it tracks the card automatically. Visible ring is 32/36 of this (r14 +
     stroke 4 in a 36 viewBox), i.e. ~0.8x the icon circle. */
  --hemma-progress-size-mq: calc(var(--hemma-icon-circle-size, 44px) * var(--hemma-progress-icon-ratio, 0.9));
  --hemma-icon-circle-size: calc(var(--hemma-entity-height-current, 200px) * var(--hemma-icon-circle-ratio, 0.22));  /* hemma_thermostat's temp puck reads this too */
  /* Every top-corner extra centers on this, so the toggle, the progress ring and
     the thermostat's rail stay in line with the icon circle at every tile size. */
  --hemma-icon-center-y: calc(
    var(--hemma-entity-inner-pad-current, var(--hemma-entity-inner-pad-desktop, 20px))
    + var(--hemma-tile-icon-mt, -2px)
    + var(--hemma-icon-circle-size, 44px) / 2);
  --hemma-entity-active-tint-current: var(--hemma-entity-active-tint, rgba(255,255,255,0.94));
  --hemma-icon-fallback-color: rgba(50,50,50,0.85);
  --hemma-toggle-off-color-active: var(--hemma-toggle-off-fill-active, rgba(0,0,0,0.55));
  --hemma-progress-arc-color: var(--hemma-progress-color, var(--hemma-color-teal, #00c3d0));
  --hemma-progress-arc-opacity: 1;

  /* Tile geometry. Only -mq is rewritten by the breakpoint; -lg never is.
     styles.card picks between them off variables.size. */
  --hemma-tile-areas-mq: "i" "n" "s";
  --hemma-tile-cols-mq: 1fr;
  --hemma-tile-rows-mq: 1fr min-content min-content;
  --hemma-tile-gap-mq: 4px 0;
  --hemma-tile-name-mb-mq: var(--hemma-name-gap-adjust, -2px);
  --hemma-tile-align-content-mq: start;
  --hemma-tile-icon-align-mq: start;
  --hemma-tile-icon-mt-mq: -2px;
  --hemma-tile-extras-mq: block;
  --hemma-tile-radius-mq: var(--hemma-tile-corner, var(--ha-card-border-radius, 28px));
  --hemma-tile-state-inset-mq: 0px;

  --hemma-tile-areas-lg: "i" "n" "s";
  --hemma-tile-cols-lg: 1fr;
  --hemma-tile-rows-lg: 1fr min-content min-content;
  --hemma-tile-gap-lg: 4px 0;
  --hemma-tile-name-mb-lg: var(--hemma-name-gap-adjust, -2px);
  --hemma-tile-align-content-lg: start;
  --hemma-tile-icon-align-lg: start;
  --hemma-tile-icon-mt-lg: -2px;
  --hemma-tile-extras-lg: block;
  --hemma-tile-radius-lg: var(--hemma-tile-corner, var(--ha-card-border-radius, 28px));
  --hemma-tile-state-inset-lg: 0px;

  /* Defaults, so first paint is correct before styles.card stamps these
     inline a frame later. */
  --hemma-tile-areas: var(--hemma-tile-areas-mq);
  --hemma-tile-cols: var(--hemma-tile-cols-mq);
  --hemma-tile-rows: var(--hemma-tile-rows-mq);
  --hemma-tile-gap: var(--hemma-tile-gap-mq);
  --hemma-tile-name-mb: var(--hemma-tile-name-mb-mq);
  --hemma-tile-align-content: var(--hemma-tile-align-content-mq);
  --hemma-tile-icon-align: var(--hemma-tile-icon-align-mq);
  --hemma-tile-icon-mt: var(--hemma-tile-icon-mt-mq);
  --hemma-tile-extras: var(--hemma-tile-extras-mq);
  --hemma-tile-radius: var(--hemma-tile-radius-mq);
  --hemma-tile-state-inset: var(--hemma-tile-state-inset-mq);
}

/* 100cqi for the auto-fitting state text = the card's content box. */
ha-card { container-type: inline-size; }

/* Rhythm on wide screens: name to state is one 1.15 line, nothing added or pulled. */
@media (min-width: 768px) and (min-height: 501px) {
  ha-card {
    --hemma-tile-gap-mq: 0 0;
    --hemma-tile-gap-lg: 0 0;
    --hemma-tile-name-mb-mq: 0px;
    --hemma-tile-name-mb-lg: 0px;
    --hemma-thermo-row-gap: 0px;
    --hemma-thermo-name-mb: -0.16em;
  }
}

/* Media list must match the one hemma-smart-row switches its grid on. */
@media (max-width: 767px) and (orientation: portrait),
       (max-height: 500px) and (orientation: portrait),
       (max-height: 600px) and (orientation: landscape) {
  ha-card {
    --hemma-height-mq: 100%;  /* the grid track owns the height */
    --hemma-icon-circle-size: 42px;
    --hemma-tile-areas-mq: "i n" "i s";
    --hemma-tile-cols-mq: auto minmax(0, 1fr);
    --hemma-tile-rows-mq: auto auto;
    --hemma-tile-gap-mq: 1px 10px;
    --hemma-tile-name-mb-mq: 0px;  /* -2px is tuned for the 4px stacked gap */
    --hemma-tile-align-content-mq: center;
    --hemma-tile-icon-align-mq: center;
    --hemma-tile-icon-mt-mq: 0px;
    --hemma-tile-icon-mt-lg: 0px;  /* or a large tile's icon sits 2px above its small neighbor */
