tap_action.service:
[[[
  if (variables.toggle_service) return variables.toggle_service;

  const target = variables.toggle_entity || entity?.entity_id || '';
  const state = (states[target]?.state || entity?.state || '').toLowerCase();
  if (state === 'unavailable' || state === 'unknown') return 'none';

  if (target.startsWith('lock.')) {
    if (state === 'locked') return 'lock.unlock';
    if (state === 'unlocked') return 'lock.lock';
    return 'none';
  }

  if (target.startsWith('media_player.')) {
    const feats = Number(states[target]?.attributes?.supported_features || 0);
    if (state === 'off') return (feats & 128) ? 'media_player.turn_on' : 'none';
    return (feats & 256) ? 'media_player.turn_off' : 'none';
  }

  return 'homeassistant.toggle';
]]]

tap_action.service_data:
[[[
  if (variables.toggle_service_data) return variables.toggle_service_data;

  return {
    entity_id: variables.toggle_entity || entity?.entity_id
  };
]]]

custom_fields.svg:
[[[
  const KF_ID = 'hemma-toggle-kf-v8';
  if (!document.getElementById(KF_ID)) {
    const s = document.createElement('style');
    s.id = KF_ID;
    s.textContent = [
      '@keyframes hemma-thumb-on-d{from{transform:translateX(0)}to{transform:translateX(18px)}}',
      '@keyframes hemma-thumb-off-d{from{transform:translateX(18px)}to{transform:translateX(0)}}'
    ].join('');
    document.head.appendChild(s);
  }
  const toggleTarget = variables.toggle_entity || entity?.entity_id || '';
  const toggleState = (states[toggleTarget]?.state || entity?.state || "").toLowerCase();
  const activeStates = ["on","open","opening","playing","unlocked","unlocking","cleaning","returning","cool","heat"];
  const extraStates = Array.isArray(variables.active_states) ? variables.active_states.map(v => String(v).toLowerCase()) : [];
  const isOn = [...activeStates, ...extraStates].includes(toggleState);
  const W = 44, H = 26, r = 9, cx0 = 14, travel = 18;
  const SW = W + 2;
  const stateKey = '_hemma_toggle_' + (entity?.entity_id || '');
  const shouldAnimate = window[stateKey] !== undefined && window[stateKey] !== isOn;
  window[stateKey] = isOn;
  const anim = isOn ? 'hemma-thumb-on-d' : 'hemma-thumb-off-d';
  const animStyle = shouldAnimate ? `animation:${anim} 0.2s ease forwards;` : '';
  const circleCx = (!shouldAnimate && isOn) ? cx0 + travel : cx0;
  const mid = 'htm-' + (entity?.entity_id || '').replace(/[^a-z0-9]/gi, '-');
  const trackFillVar = getComputedStyle(document.documentElement).getPropertyValue('--hemma-toggle-track-fill').trim();
  const trackFill = trackFillVar || 'rgba(255,255,255,0.85)';
  const offColor = 'var(--hemma-toggle-off-color, rgba(255,255,255,0.8))';
  if (isOn) {
    return `<svg viewBox="0 0 ${SW} ${H}" style="display:block;width:100%;height:100%;overflow:visible;"><defs><mask id="${mid}"><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="white"/><circle cx="${circleCx}" cy="${H/2}" r="${r}" fill="black" style="${animStyle}"/></mask></defs><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="${trackFill}" mask="url(#${mid})"/></svg>`;
  } else {
    return `<svg viewBox="0 0 ${SW} ${H}" style="display:block;width:100%;height:100%;overflow:visible;"><rect x="2" y="1" width="${W-2}" height="${H-2}" rx="${(H-2)/2}" fill="none" stroke-width="2" style="stroke:${offColor};"/><circle cx="${circleCx}" cy="${H/2}" r="${r}" style="${animStyle}fill:${offColor};"/></svg>`;
  }
]]]

