custom_fields.battery:
[[[
  const batt = variables.battery_entity;
  if (!batt) return "";
  const st = states[batt];
  if (!st) return "";
  const raw = (st.state ?? "").toString().toLowerCase();
  const isLowWord = ["low", "critical"].includes(raw);
  const n = parseFloat(raw);
  const hasNum = Number.isFinite(n);
  const threshold = Number(variables.battery_low_threshold ?? 20);
  const isLowNum = hasNum && n <= threshold;
  if (!(isLowWord || isLowNum)) return "";
  const size = (window.innerWidth < 768) ? 20 : 24;
  return `
    <ha-icon
      icon="mdi:battery-alert"
      style="
        --mdc-icon-size:${size}px;
        color: var(--hemma-entity-state, var(--secondary-text-color));
        opacity: .7;
      "
    ></ha-icon>
  `;
]]]

custom_fields.progress:
[[[
  const PROP_ID = 'hemma-progress-property-v2';
  if (!document.getElementById(PROP_ID)) {
    const s = document.createElement('style');
    s.id = PROP_ID;
    s.textContent = '@property --hemma-progress-pct { syntax: "<number>"; inherits: true; initial-value: 0; }';
    document.head.appendChild(s);
  }

  const dom = (entity?.entity_id || '').split('.')[0];
  const st = (entity?.state || '').toLowerCase();
  const feats = Number(entity?.attributes?.supported_features || 0);

  let glyph = '', svc = '';
  if (variables.progress_transport) {
    if (dom === 'media_player' && (feats & 16385)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = 'media_player.media_play_pause';
    } else if (dom === 'vacuum' && (feats & 4)) {
      glyph = st === 'paused' ? 'play' : 'pause';
      svc = st === 'paused' ? 'vacuum.start' : 'vacuum.pause';
    }
  }

  const GLYPHS = {
    pause: '<rect class="hemma-progress-glyph" x="14" y="13" width="2.6" height="10" rx="1.3"/>'
         + '<rect class="hemma-progress-glyph" x="19.4" y="13" width="2.6" height="10" rx="1.3"/>',
    play:  '<path class="hemma-progress-glyph" d="M15.4 12.9 L23.8 18 L15.4 23.1 Z"'
         + ' stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round"/>',
  };

  let inner = '';
  if (glyph && svc) {
    const [d, sv] = svc.split('.');
    const stop = 'event.stopPropagation();event.stopImmediatePropagation();';
    const act = stop + "document.querySelector('home-assistant').hass.callService('"
              + d + "','" + sv + "',{entity_id:'" + entity?.entity_id + "'});";
    inner = `<g style="cursor:pointer;pointer-events:auto;" onpointerdown="${stop}" ontouchstart="${stop}" onclick="${act}">`
          + `<circle cx="18" cy="18" r="12" fill="transparent"/>${GLYPHS[glyph]}</g>`;
  }

  return `<svg viewBox="0 0 36 36" xmlns="http://www.w3.org/2000/svg" style="display:block;width:100%;height:100%;overflow:visible;">
    <g transform="rotate(-90 18 18)">
      <circle class="hemma-progress-track" cx="18" cy="18" r="14" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="4" stroke-linecap="round"/>
      <circle class="hemma-progress-arc" cx="18" cy="18" r="14" fill="none" stroke="var(--hemma-color-teal, #00c3d0)" stroke-width="4" stroke-linecap="round" stroke-dasharray="87.965"/>
    </g>
    ${inner}
  </svg>`;
]]]

