hemma_entity.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  if (!entity?.state) return "";
  if (entity.state === "ok") return T('state.healthy', 'Healthy');
  // Switching HA's language swaps localize while the new strings are
  // still loading, and formatEntityState throws for that window.
  try { return hass.formatEntityState(entity) || entity.state; }
  catch (e) { return entity.state; }
]]]

state.value:
[[[
  if (variables.active_override !== null && variables.active_override !== undefined) {
    return !!variables.active_override;
  }

  const defaults = ["on","open","opening","unlocked","unlocking","playing","cleaning","returning","cool","heat","washing","rinsing","spinning","drying","running","active","problem"];
  const extra = Array.isArray(variables.active_states) ? variables.active_states.map(v => String(v).toLowerCase()) : [];
  const activeStates = [...defaults, ...extra];

  if (activeStates.includes((entity?.state || "").toLowerCase())) return true;

  const list = Array.isArray(variables.active_entities)
    ? variables.active_entities.filter(Boolean)
    : (variables.active_entities ? [variables.active_entities] : []);
  if (!list.length) return false;

  const isOn = (eid) => activeStates.includes(String(states[eid]?.state || "").toLowerCase());

  return String(variables.active_entities_mode || "any").toLowerCase() === "all"
    ? list.every(isOn)
    : list.some(isOn);
]]]

card.--hemma-icon-color-current:
[[[
  const icon   = variables.icon || '';
  const domain = (entity?.entity_id || '').split('.')[0];
  if (icon === 'energy' || icon === 'power') {
    const pid = variables.entity_power || entity?.entity_id;
    const w = parseFloat(states[pid]?.state);
    if (!Number.isFinite(w)) return 'var(--hemma-badge-energy-color, #30D158)';
    if (w >= Number(variables.extreme_threshold ?? 3000)) return 'var(--hemma-badge-energy-very-high-color, #FF4245)';
    if (w >= Number(variables.heavy_threshold   ?? 1000)) return 'var(--hemma-badge-energy-high-color, #FF9230)';
    if (w >= Number(variables.normal_threshold  ?? 200))  return 'var(--hemma-badge-energy-medium-color, #FFD600)';
    return 'var(--hemma-badge-energy-low-color, #30D158)';
  }
  const byIcon = {
    plant:    'var(--hemma-color-yellow, #FFCC00)',
    updates:  'var(--hemma-color-teal, #00c3d0)',
    wifi:     'var(--hemma-popup-primary-color, #00c3d0)',
    doorbell: 'var(--hemma-color-teal, #00c3d0)',
  };
  const byDomain = {
    light:        'var(--hemma-color-yellow, #FFCC00)',
    fan:          'var(--hemma-color-teal, #00C3D0)',
    humidifier:   'var(--hemma-color-teal, #00C3D0)',
    climate:      'var(--hemma-color-teal, #00C3D0)',
    vacuum:       'var(--hemma-badge-vacuum-color, var(--hemma-color-orange, #FF9230))',
    cover:        'var(--hemma-color-teal, #00c3d0)',
    media_player: 'var(--hemma-color-teal, #00c3d0)',
    lock:         entity?.state === 'unlocking' ? 'var(--hemma-color-yellow, #FFCC00)' : 'var(--hemma-color-teal, #00c3d0)',
    plant:        'var(--hemma-color-yellow, #FFCC00)',
  };
  return byIcon[icon] || byDomain[domain] || 'var(--hemma-icon-fallback-color, rgba(255,255,255,0.95))';
]]]

card.--hemma-icon-svg-url:
[[[
  const pic = entity?.attributes?.entity_picture || '';
  if (pic && pic.startsWith('/local/')) return `url('${pic}')`;
  const icon = variables.icon || 'default';
  return `url('${window.hemmaIconUrl(icon)}')`;
]]]

card.--hemma-icon-use-mask:
[[[
  const pic = entity?.attributes?.entity_picture || '';
  if (pic && (pic.startsWith('/api/') || pic.startsWith('http'))) return '0';
  return '1';
]]]

card.--hemma-entity-anim-name:
[[[
  if (!window._hemmaAnimSetup) {
    window._hemmaAnimSetup = true;
    try { const at = Number(sessionStorage.getItem('hemma_bg_at') || 0); window._hemmaFromBg = !!at && Date.now() - at < 864e5; } catch (_) { window._hemmaFromBg = false; }
    window._hemmaLastPath = window.location.pathname;
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) window._hemmaFromBg = true;
    });
    window.addEventListener('location-changed', () => {
      const newPath = window.location.pathname;
      if (newPath !== window._hemmaLastPath) {
        window._hemmaFromBg = false;
      }
      window._hemmaLastPath = newPath;
    });
  }
  return window._hemmaFromBg ? 'none' : 'hemmaFadeIn';
]]]

card.--hemma-icon-inactive-color:
[[[
  const icon   = variables.icon || '';
  const domain = (entity?.entity_id || '').split('.')[0];
  if (domain === 'media_player') return 'var(--hv-icon-off, var(--hemma-icon-inactive-fallback-color, rgba(255,255,255,0.95)))';
  if (icon === 'energy' || icon === 'power') {
    const pid = variables.entity_power || entity?.entity_id;
    const w = parseFloat(states[pid]?.state);
    if (!Number.isFinite(w)) return 'var(--hv-icon-off, var(--hemma-badge-energy-color, #30D158))';
    const hi = Number(variables.high_threshold ?? 500), act = w >= (this._hemmaEnergyActive === true ? Number(variables.release_threshold ?? hi * 0.8) : hi);
    const off = (c) => act ? c : 'var(--hv-icon-off, ' + c + ')';
    if (w >= Number(variables.extreme_threshold ?? 3000)) return off('var(--hemma-badge-energy-very-high-color, #FF4245)');
    if (w >= Number(variables.heavy_threshold   ?? 1000)) return off('var(--hemma-badge-energy-high-color, #FF9230)');
    if (w >= Number(variables.normal_threshold  ?? 200))  return off('var(--hemma-badge-energy-medium-color, #FFD600)');
    return 'var(--hv-icon-off, var(--hemma-badge-energy-low-color, #30D158))';
  }
  const byIcon = {
    plant:    'var(--hemma-color-green, #30D158)',
    wifi:     'var(--hemma-popup-primary-color, #00c3d0)',
    doorbell: 'var(--hemma-color-teal, #00c3d0)',
  };
  const byDomain = {
    light:        'var(--hv-icon-off-light, var(--hemma-color-yellow, #FFCC00))',
    fan:          'var(--hemma-color-teal, #00C3D0)',
    humidifier:   'var(--hemma-color-teal, #00C3D0)',
    climate:      'var(--hemma-color-teal, #00C3D0)',
    vacuum:       'var(--hemma-badge-vacuum-color, var(--hemma-color-orange, #FF9230))',
    cover:        'var(--hemma-color-teal, #00c3d0)',
    lock:         'var(--hemma-color-teal, #00c3d0)',
    plant:        'var(--hemma-color-green, #30D158)',
  };
  return 'var(--hv-icon-off, ' + (byIcon[icon] || byDomain[domain] || 'var(--hemma-icon-inactive-fallback-color, rgba(255,255,255,0.95))') + ')';
]]]

card.display:
[[[
  return (states['input_boolean.hemma_mobile_navigation']?.state === 'on') ? 'none' : 'block';
]]]

card.--hemma-progress-pct:
[[[
  if (!variables.show_progress) return 0;

  let v = variables.progress_value;

  if (v === null || v === undefined) {
    const target = variables.progress_entity || entity?.entity_id;
    const st = states[target];

    if (!st) return 0;

    const rawState = st.state;
    const attrs = st.attributes || {};

    const stateNum = parseFloat(rawState);
    if (Number.isFinite(stateNum)) {
      v = stateNum;
    }

    else if (Number.isFinite(Number(attrs.percentage))) {
      v = Number(attrs.percentage);
    } else if (Number.isFinite(Number(attrs.progress))) {
      v = Number(attrs.progress);
    }

    else if (
      Number.isFinite(Number(attrs.media_position)) &&
      Number.isFinite(Number(attrs.media_duration)) &&
      Number(attrs.media_duration) > 0
    ) {
      const position = Number(attrs.media_position);
      const duration = Number(attrs.media_duration);
      const stateNow = (st.state || '').toLowerCase();

      let effectivePosition = position;

      if (
        stateNow === 'playing' &&
        attrs.media_position_updated_at
      ) {
        const updatedAt = new Date(attrs.media_position_updated_at).getTime();
        if (Number.isFinite(updatedAt)) {
          const elapsed = Math.max(0, (Date.now() - updatedAt) / 1000);
          effectivePosition += elapsed;
        }
      }

      effectivePosition = Math.max(0, Math.min(duration, effectivePosition));
      v = (effectivePosition / duration) * 100;
    }

    else {
      v = 0;
    }
  }

  const n = Number(v);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 0;
]]]

card.--hemma-progress-display:
[[[
  if (!variables.show_progress) return 'none';
  const activeStates = variables.progress_active_states || [];
  const s = (entity?.state || '').toLowerCase();
  return activeStates.includes(s) ? 'var(--hemma-tile-extras, block)' : 'none';
]]]

toggle.display:
[[[
  if (!variables.show_toggle) return 'none';
  const target = variables.toggle_entity || entity?.entity_id || '';
  const tState = (states[target]?.state || entity?.state || '').toLowerCase();
  if (tState === 'unavailable' || tState === 'unknown') return 'none';
  if (target.startsWith('media_player.')) {
    const feats = states[target]?.attributes?.supported_features;
    if (typeof feats === 'number' && !(feats & 384)) return 'none';
  }
  if (variables.show_progress) {
    const activeStates = variables.progress_active_states || [];
    const s = (entity?.state || '').toLowerCase();
    if (activeStates.includes(s)) return 'none';
  }
  return 'var(--hemma-tile-extras, block)';
]]]

