/* MUST match hemma_settings_button and .np-head-wave: same size, same flat
   fill, blur but no rim. Three controls on one row read as one set only if
   nothing about them disagrees. */
:host ha-card{
  /* styles.card lands the var on ha-card, so it is read here - a custom
     property set on a child is invisible to its parent. */
