hemma_scene_core_guard.value:
[[[
    if (typeof window._hemmaSC !== 'object' || window._hemmaSCv !== 24) {
      window._hemmaSCv = 24;

      const CFG_KEY = 'hemma_scene_cfg_v1';
      const IGN_KEY = 'hemma_scene_ignore_v1';
      const UD_KEY = 'hemma_scene_ignore';

      const SETTLE_PAD_MS = 1500;
      const settleMs = (t) => (Number(t) || 0) * 1000 + SETTLE_PAD_MS;

      const load = (k) => { try { return JSON.parse(localStorage.getItem(k) || '{}') || {}; } catch (_) { return {}; } };
      const save = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (_) {} };

      const cfgCache = load(CFG_KEY);
      const ignore   = load(IGN_KEY);
      const noCfg    = new Set();
      let apiDead    = false;
      let optimistic = null;
      const inFlight = new Set();
      const refreshed = new Set();

      const els = new Set();
      window._hemmaSCReg = (el) => { if (el) els.add(el); };

      const SORT_HOLD_MS = 2500;
      const SORT_MS      = 450;
      const SORT_EASE    = 'cubic-bezier(0.4, 0, 0.2, 1)';  // matches SORT_MS/EASE in smart-row.js
      const seenIds      = new Set();
      let   heldActive   = null;
      let   sortTimer    = null;
      let   firstSort    = true;
      let   noAnimUntil  = 0;
      let   userTapped   = false;
      let   sortNotBefore = 0;
      let   tapSurface   = null;
      const flipStat     = { runs: 0, moved: 0, skipped: '', stores: [], chips: 0, frozen: 0 };
      let   storeSeq     = 0;
      // Keyed by surface, not by element: smart-row rebuilds its children, and
      // anything cached on the card dies with it.
      const surfaces     = new Map();
      const surfaceOf = (key) => {
        let su = surfaces.get(key || 'default');
        if (!su) { su = { rects: null, freezeUntil: 0, flipTs: 0, html: '', id: ++storeSeq }; surfaces.set(key || 'default', su); }
        return su;
      };
      const reduceMotion = () => {
        try { return window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (_) { return false; }
      };
      const nudge = () => els.forEach((el) => {
        try { if (el.isConnected === false) { els.delete(el); return; } el.requestUpdate && el.requestUpdate(); } catch (_) {}
      });

      const liveHass = () => document.querySelector('home-assistant')?.hass || null;

      // Hold before re-sorting: a scene you just tapped must not jump out
      // from under your finger, and a strip mid-scroll must not reflow.
      const scheduleSort = () => {
        if (sortTimer) return;
        // Boot means the configs arriving, not anything the user did. Once a
        // scene has been tapped, every sort is a real one and animates.
        const first = firstSort && !userTapped;
        // Wait out the scene transition: while lights fade, every state change
        // re-renders the row and replaces the chips mid-animation.
        const wait = first ? 350 : Math.max(SORT_HOLD_MS, sortNotBefore - Date.now());
        sortTimer = setTimeout(function run() {
          if (!first && Date.now() - (window._hemmaSCBusy || 0) < 1200) { sortTimer = setTimeout(run, 800); return; }
          sortTimer = null;
          firstSort = false;
          if (first) noAnimUntil = Date.now() + 800;
          const st = liveHass()?.states || null;
          if (st) heldActive = window._hemmaSC.activeList(Array.from(seenIds), st);
          tapSurface = null;
          nudge();
        }, wait);
      };

      const eqArr = (a, b) => Array.isArray(a) && Array.isArray(b)
        && a.length === b.length && a.every((v, i) => v === b[i]);

      const SC_C = {
        onBg: 'var(--hemma-entity-active-tint-current, rgba(255,255,255,0.94))',
        offBg: 'var(--hemma-entity-background, rgba(0,0,0,0.40))',
        onName: 'var(--hemma-entity-name-active, rgba(0,0,0,0.88))',
        offName: 'var(--hemma-scene-name-off, rgba(255,255,255,0.90))',
        rim: 'var(--hemma-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10))',
        backdrop: 'var(--hemma-scene-chip-backdrop, blur(22px) saturate(1.2))',
      };

      const EFFECT_OFF = new Set(['off', 'none', 'no effect', 'effect_stop', 'solid']);
      const effectIsOff = (v) => v == null || EFFECT_OFF.has(String(v).toLowerCase());

      const attrMatch = (t, live) => {
        const la = live.attributes || {};

        if (!effectIsOff(t.effect)) return String(la.effect) === String(t.effect);
        if (t.effect != null && !effectIsOff(la.effect)) return false;

        if (t.brightness != null && t.brightness !== la.brightness) return false;
        const mode = t.color_mode;
        if (mode != null && mode !== la.color_mode) return false;
        if (mode === 'color_temp') {
          if (t.color_temp_kelvin != null && t.color_temp_kelvin !== la.color_temp_kelvin) return false;
        } else if (mode != null) {
          if (t.rgb_color != null && !eqArr(t.rgb_color, la.rgb_color)) return false;
        }
        return true;
      };

      const roomEntityIds = (hass, roomName) => {
        const areas = hass?.areas || {};
        const devices = hass?.devices || {};
        const ents = hass?.entities || {};
        const want = String(roomName || '').trim().toLowerCase();
        if (!want) return null;
        const areaIds = new Set(Object.keys(areas)
          .filter((id) => String(areas[id]?.name || '').trim().toLowerCase() === want));
        if (!areaIds.size) return null;
        const out = new Set();
        Object.keys(ents).forEach((eid) => {
          const e = ents[eid];
          const aid = e?.area_id || (e?.device_id ? devices[e.device_id]?.area_id : null);
          if (aid && areaIds.has(aid)) out.add(eid);
        });
        return out.size ? out : null;
      };

      const expandEntity = (eid, states, seen) => {
        seen = seen || new Set();
        if (!eid || seen.has(eid)) return [];
        seen.add(eid);
        const mems = states[eid]?.attributes?.entity_id;
        if (Array.isArray(mems)) return mems.flatMap((m) => expandEntity(m, states, seen));
        return [eid];
      };

      const sceneTouchesRoom = (sceneId, states, roomSet) => {
        const targets = states[sceneId]?.attributes?.entity_id;
        if (!Array.isArray(targets)) return false;
        for (const t of targets) {
          if (typeof t !== 'string') continue;
          if (roomSet.has(t)) return true;
          const leaves = expandEntity(t, states);
          for (const l of leaves) if (roomSet.has(l)) return true;
        }
        return false;
      };

      // Overview's category pages: a scene belongs to every kind of thing it sets (hemma-core's hemmaEntityCategory).
      const sceneTouchesCategory = (sceneId, states, cat) => {
        const kind = window.hemmaEntityCategory;
        const targets = states[sceneId]?.attributes?.entity_id;
        if (typeof kind !== 'function' || !Array.isArray(targets)) return false;
        return targets.some((t) => typeof t === 'string'
          && (kind(t) === cat || expandEntity(t, states).some((l) => kind(l) === cat)));
      };

      const entityMatch = (eid, t, states) => {
        const live = states[eid];
        if (!live) return false;
        if (String(t.state) !== String(live.state)) return false;
        if (String(t.state) !== 'on') return true;
        if (!eid.startsWith('light.')) return true;
        return attrMatch(t, live);
      };

      const fetchCfg = (sceneId) => {
        if (apiDead || noCfg.has(sceneId) || inFlight.has(sceneId)) return;
        const h = liveHass();
        if (!h) return;
        const sid = h.states[sceneId]?.attributes?.id;
        if (!sid) { noCfg.add(sceneId); return; }
        inFlight.add(sceneId);
        h.callApi('GET', 'config/scene/config/' + sid).then((c) => {
          inFlight.delete(sceneId);
          if (c && c.entities) {
            const changed = JSON.stringify(cfgCache[sceneId]) !== JSON.stringify(c);
            cfgCache[sceneId] = c;
            save(CFG_KEY, cfgCache);
            if (changed) nudge();
          }
        }).catch((e) => {
          inFlight.delete(sceneId);
          const code = e?.status_code || e?.status;
          if (code === 401 || code === 403) apiDead = true;
          else noCfg.add(sceneId);
        });
      };

      let udPulled = false;
      let udPullAt = 0;

      const pullShared = (force) => {
        const h = liveHass();
        if (!h || !h.callWS) return;
        if (!force && udPulled) return;
        if (Date.now() - udPullAt < 3000) return;
        udPulled = true;
        udPullAt = Date.now();
        h.callWS({ type: 'frontend/get_user_data', key: UD_KEY }).then((r) => {
          const v = r && r.value;
          if (!v || typeof v !== 'object') return;
          if (JSON.stringify(v) === JSON.stringify(ignore)) return;
          Object.keys(ignore).forEach((k) => delete ignore[k]);
          Object.keys(v).forEach((k) => { ignore[k] = v[k]; });
          save(IGN_KEY, ignore);
          nudge();
        }).catch(() => {});
      };

      const pushShared = () => {
        const h = liveHass();
        if (!h || !h.callWS) return;
        udPullAt = Date.now();
        h.callWS({ type: 'frontend/set_user_data', key: UD_KEY, value: ignore }).catch(() => {});
      };

      const seenTs = {};
      const watchForRemoteApply = (ids, states) => {
        let changed = false;
        (ids || []).forEach((id) => {
          const t = states[id]?.state;
          if (seenTs[id] !== undefined && seenTs[id] !== t) changed = true;
          seenTs[id] = t;
        });
        if (changed) setTimeout(() => pullShared(true), 6000);
      };

      const learn = (sceneId) => {
        const cfg = cfgCache[sceneId];
        const h = liveHass();
        if (!cfg || !h) return;
        const ents = cfg.entities || {};
        const ids = Object.keys(ents);
        if (!ids.length) return;
        const bad = ids.filter((eid) => !entityMatch(eid, ents[eid], h.states));
        if (bad.length > ids.length / 2) return;
        const set = new Set(ignore[sceneId] || []);
        const badSet = new Set(bad);
        ids.forEach((eid) => { if (badSet.has(eid)) set.add(eid); else set.delete(eid); });
        const before = JSON.stringify(ignore[sceneId] || null);
        if (set.size) ignore[sceneId] = Array.from(set); else delete ignore[sceneId];
        save(IGN_KEY, ignore);
        if (JSON.stringify(ignore[sceneId] || null) !== before) { pushShared(); nudge(); }
      };

      window._hemmaSC = {
        iconColors: {},

        noteColors(map) {
          // A YAML list of single-key maps is the easy slip next to `scenes:`.
          if (Array.isArray(map)) map = Object.assign({}, ...map.filter((x) => x && typeof x === 'object'));
          if (map && typeof map === 'object') Object.assign(this.iconColors, map);
        },

        list(states, hass, vars) {
          const v = vars || {};
          const reg = hass?.entities || {};
          const getReg = (id) => reg[id] || (reg.get && reg.get(id)) || null;
          const excl = new Set(Array.isArray(v.scene_exclude) ? v.scene_exclude : []);

          const explicit = Array.isArray(v.scenes) && v.scenes.length > 0;
          let ids = explicit
            ? v.scenes.filter((id) => states[id])
            : Object.keys(states || {})
                .filter((id) => id.startsWith('scene.') && !id.startsWith('scene.hemma'))
                .filter((id) => {
                  const re = getReg(id);
                  return re && !(re.hidden || re.hidden_by || re.disabled || re.disabled_by);
                });

          ids = ids.filter((id) => !excl.has(id));

          if (v.room) {
            const roomSet = roomEntityIds(hass, v.room);
            if (roomSet) ids = ids.filter((id) => sceneTouchesRoom(id, states, roomSet));
          }
          if (v.category) ids = ids.filter((id) => sceneTouchesCategory(id, states, v.category));
          if (!explicit) {
            const nameOf = (id) => states[id]?.attributes?.friendly_name
              || id.replace('scene.', '').replace(/_/g, ' ');
            ids.sort((a, b) => nameOf(a).localeCompare(nameOf(b)));
          }

          if (Array.isArray(v.scene_order)) {
            const so = v.scene_order;
            ids.sort((a, b) => {
              const ai = so.indexOf(a), bi = so.indexOf(b);
              if (ai !== -1 && bi !== -1) return ai - bi;
              if (ai !== -1) return -1;
              if (bi !== -1) return 1;
              return 0;
            });
          }
          return ids;
        },

        prefetch(ids, states) {
          pullShared(false);
          if (states) watchForRemoteApply(ids, states);
          (ids || []).forEach((id) => {
            if (!cfgCache[id]) { fetchCfg(id); return; }
            if (!refreshed.has(id)) { refreshed.add(id); fetchCfg(id); }
          });
        },

        isActive(sceneId, states) {
          if (optimistic && optimistic.id === sceneId && Date.now() < optimistic.until) return true;
          const cfg = cfgCache[sceneId];
          if (!cfg || !cfg.entities) return false;
          const ign = new Set(ignore[sceneId] || []);
          const ents = cfg.entities;
          let checked = 0;
          for (const eid of Object.keys(ents)) {
            if (ign.has(eid)) continue;
            if (!entityMatch(eid, ents[eid], states)) return false;
            checked++;
          }
          return checked > 0;
        },

        activeList(ids, states) {
          const ts = (id) => {
            const t = Date.parse(states[id]?.state);
            return isNaN(t) ? 0 : t;
          };
          return (ids || [])
            .filter((id) => this.isActive(id, states))
            .sort((a, b) => ts(b) - ts(a));
        },

        activeOf(ids, states) {
          return this.activeList(ids, states)[0] || null;
        },

        // Visual order only: the caller keeps building chips in its own
        // order, so the DOM stays stable and flip() has something to move.
        order(ids, states, sid) {
          const list = ids || [];
          list.forEach((id) => seenIds.add(id));
          const live = this.activeList(list, states);
          if (heldActive === null) heldActive = live;
          else {
            const liveSet = new Set(live);
            const heldSet = new Set(heldActive);
            if (list.some((id) => liveSet.has(id) !== heldSet.has(id))) scheduleSort();
          }
          // The hold exists so a tapped chip cannot jump out from under the
          // finger. Every other surface is off-screen, so it sorts now and is
          // already correct when the user gets back to it.
          const held = (tapSurface != null && sid != null && sid !== tapSurface)
            ? live : (heldActive || []);
          const rank = new Map();
          held.forEach((id, i) => rank.set(id, i));
          const active = list.filter((id) => rank.has(id)).sort((a, b) => rank.get(a) - rank.get(b));
          const rest   = list.filter((id) => !rank.has(id));
          const out = new Map();
          active.concat(rest).forEach((id, i) => out.set(id, i));
          return out;
        },

        // FLIP across renders: chips are rebuilt from innerHTML every time,
        // so positions are cached per container and keyed by scene id.
        flip(el, key) {
          // The caller may hand us the field element, the card, or the card's
          // shadow root; find whichever one actually holds chips.
          const cands = [];
          if (el) {
            cands.push(el);
            if (el.shadowRoot) cands.push(el.shadowRoot);
            const h = el.getRootNode && el.getRootNode().host;
            if (h) { cands.push(h); if (h.shadowRoot) cands.push(h.shadowRoot); }
          }
          let root = null;
          for (let i = 0; i < cands.length; i++) {
            const c = cands[i];
            if (c && c.querySelector && c.querySelector('[data-scene]')) { root = c; break; }
          }
          if (!root) { flipStat.runs++; flipStat.skipped = 'no-chips-found'; return; }
          const nodes = Array.from(root.querySelectorAll('[data-scene]'));
          const su = surfaceOf(key);
          if (su.flipTs && Date.now() - su.flipTs < 50) return;
          su.flipTs = Date.now();
          // Overlays are built inside a display:none subtree, so every offset
          // reads 0 and a snapshot taken here would fling each chip in from
          // the container's corner on the next render.
          if (!nodes.some((n) => n.offsetWidth || n.offsetHeight)) {
            su.rects = null;
            flipStat.runs++;
            flipStat.skipped = 'not-laid-out';
            return;
          }
          flipStat.stores.push(su.id);
          if (flipStat.stores.length > 6) flipStat.stores.shift();
          flipStat.chips = nodes.length;
          const prev = su.rects;
          const cur = {};
          nodes.forEach((n) => { cur[n.dataset.scene] = { l: n.offsetLeft, t: n.offsetTop }; });
          su.rects = cur;
          flipStat.runs++;
          flipStat.skipped = !prev ? 'no-previous-positions'
            : reduceMotion() ? 'prefers-reduced-motion'
            : Date.now() < noAnimUntil ? 'boot-window'
            : (tapSurface != null && su.id !== tapSurface) ? 'other-surface' : '';
          if (flipStat.skipped) return;
          let moved = 0;
          nodes.forEach((n) => {
            const p = prev[n.dataset.scene];
            if (!p) return;
            const c = cur[n.dataset.scene];
            const dx = p.l - c.l, dy = p.t - c.t;
            if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
            moved++;
            const t0 = n.style.transition;
            n.style.transition = 'none';
            n.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
            requestAnimationFrame(() => requestAnimationFrame(() => {
              n.style.transition = 'transform ' + SORT_MS + 'ms ' + SORT_EASE;
              n.style.transform = '';
              setTimeout(() => { n.style.transition = t0; }, SORT_MS + 60);
            }));
          });
          flipStat.moved = moved;
          if (!moved) flipStat.skipped = 'no-position-change';
          else {
            // Every light the scene touches re-renders the row, and a re-render
            // swaps in fresh chips mid-transition. Hold the markup steady until
            // the slide is done: an identical string means no DOM churn.
            su.freezeUntil = Date.now() + SORT_MS + 120;
            flipStat.frozen++;
          }
        },

        chipHtml(sceneId, states, opts) {
          const o = opts || {};
          const on = this.isActive(sceneId, states);
          const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
            .replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
          const st = states[sceneId];
          const name = esc(st?.attributes?.friendly_name
            || sceneId.replace('scene.', '').replace(/_/g, ' '));
          const trans = o.transition == null ? 4 : o.transition;
          const accent = 'var(--hemma-color-yellow, #FFCC00)';
          const clr = o.color || this.iconColors[sceneId] || null;
          const tint = on
            ? (clr ? String(clr).replace(/["<>]/g, '') : accent)
            : SC_C.offName;

          const glyph = o.icon
            ? '<div style="width:26px;height:26px;background-color:' + tint
              + ';transition:background-color 0.45s ease'
              + ';-webkit-mask:url(' + esc(o.icon) + ') no-repeat center/contain;mask:url('
              + esc(o.icon) + ') no-repeat center/contain;"></div>'
            : '<ha-icon icon="' + esc(st?.attributes?.icon || 'mdi:palette')
              + '" style="--mdc-icon-size:26px;transition:color 0.45s ease;color:' + tint + ';"></ha-icon>';

          const sizing = (o.grid
            ? 'width:100%;'
            : 'flex:0 0 auto;width:' + (o.width || '41vw') + ';')
            + (o.order == null ? '' : 'order:' + o.order + ';');

          const tap = ' onpointerdown="this.dataset.sx=event.clientX;this.dataset.sy=event.clientY"'
            + ' onpointerup="var dx=Math.abs(event.clientX-this.dataset.sx),'
            + 'dy=Math.abs(event.clientY-this.dataset.sy);if(dx>8||dy>8)return;'
            + 'event.stopPropagation();window._hemmaSC&amp;&amp;window._hemmaSC.apply(&#39;'
            + sceneId + '&#39;,' + trans + ',' + (o.sid == null ? 'null' : o.sid) + ')"';

          return '<div role="button" tabindex="0" data-scene="' + esc(sceneId) + '"' + tap
            + ' style="' + sizing
            + 'display:flex;align-items:center;gap:10px;padding:12px;box-sizing:border-box;'
            // One height and radius for every surface: the home row and the
            // Scenes page are the same component and must not diverge.
            + 'min-height:var(--hemma-scene-tile-h, 56px);'
            + 'border-radius:var(--hemma-scene-tile-radius, 20px);'
            + 'cursor:pointer;pointer-events:auto;-webkit-tap-highlight-color:transparent;'
            + 'user-select:none;-webkit-user-select:none;'
            + 'transition:background 0.45s ease,transform 0.2s ease;'
            + 'box-shadow:' + SC_C.rim + ';'
            + '-webkit-backdrop-filter:' + SC_C.backdrop + ';backdrop-filter:' + SC_C.backdrop + ';'
            + 'background:' + (on ? SC_C.onBg : SC_C.offBg) + ';">'
              + '<div style="width:28px;height:28px;min-width:28px;display:flex;'
                + 'align-items:center;justify-content:center;">' + glyph + '</div>'
              + '<div style="font-size:14px;font-weight:500;line-height:1.2;white-space:nowrap;'
                + 'overflow:hidden;text-overflow:ellipsis;font-family:var(--primary-font-family,system-ui);'
                + 'color:' + (on ? SC_C.onName : SC_C.offName) + ';">' + name + '</div>'
            + '</div>';
        },

        chip(sceneId, opts) {
          const o = opts || {};
          const sid = JSON.stringify(sceneId);
          const icon = o.icon || null;
          const trans = o.transition == null ? 4 : o.transition;
          const act = 'var _sca = window._hemmaSC ? window._hemmaSC.isActive(' + sid + ', states) : false;';
          const maskCss = icon
            ? '#img-cell img{opacity:0!important;}div#img-cell::after{content:""!important;display:block!important;position:absolute!important;inset:0!important;background-color:var(--sc-clr,#ffffff)!important;-webkit-mask-image:url(' + JSON.stringify(icon) + ')!important;-webkit-mask-repeat:no-repeat!important;-webkit-mask-position:center!important;-webkit-mask-size:auto 58%!important;mask-image:url(' + JSON.stringify(icon) + ')!important;mask-repeat:no-repeat!important;mask-position:center!important;mask-size:auto 58%!important;pointer-events:none!important;transform:translateZ(0)!important;}'
            : '';
          const card = [
            { background: '[[[ ' + act + ' return _sca?"' + SC_C.onBg + '":"' + SC_C.offBg + '"; ]]]' },
            { '--sc-nc': '[[[ ' + act + ' return _sca?"' + SC_C.onName + '":"' + SC_C.offName + '"; ]]]' },
            { '--sc-clr': '[[[ ' + act + ' return _sca?"#ffffff":"var(--hemma-color-yellow, #FFCC00)"; ]]]' },
            { '--hemma-card-hover-filter': '[[[ ' + act + ' return _sca?"none":"brightness(1.10)"; ]]]' },
            { '--sc-hover-tint': '[[[ ' + act + ' return _sca?"transparent":"rgba(255,255,255,0.06)"; ]]]' },
            { border: 'none' },
            { 'box-shadow': 'none' },
            { 'border-radius': '26px' },
            { cursor: 'pointer' },
            { padding: '12px 12px' },
            { width: o.width || '100%' },
          ];
          if (o.width) card.push({ 'min-width': o.width });
          return {
            type: 'custom:button-card',
            entity: sceneId,
            tap_action: {
              action: 'fire-dom-event',
              event_data: { hemma_scene_tap: sceneId, hemma_scene_transition: trans },
            },
            haptic: 'medium',
            show_icon: true,
            show_entity_picture: true,
            entity_picture: '[[[ return ' + JSON.stringify(icon) + ' || states[' + sid + ']?.attributes?.entity_picture || undefined; ]]]',
            icon: '[[[ return states[' + sid + ']?.attributes?.icon || "mdi:palette"; ]]]',
            show_name: true,
            show_state: false,
            show_label: false,
            name: '[[[ return states[' + sid + ']?.attributes?.friendly_name || ' + sid + '.replace("scene.", "").replace(/_/g, " "); ]]]',
            extra_styles: ':host{--hemma-card-hover-filter:brightness(1.10);width:100%!important;max-width:none!important;display:block!important;box-sizing:border-box!important;--button-card-ripple-color:transparent!important;--button-card-ripple-hover-color:transparent!important;--ha-ripple-color:transparent!important;--ha-ripple-hover-color:transparent!important;}ha-card{transition:background 0.45s ease,transform var(--hemma-popup-tile-hover-duration,0.2s) ease,filter var(--hemma-popup-tile-hover-duration,0.2s) ease!important;transform:scale(1)!important;}ha-card:hover{transform:scale(var(--hemma-popup-tile-hover-scale,1.01))!important;}ha-card:active{transform:scale(0.97)!important;}@media (hover:hover){ha-card:hover{filter:var(--hemma-card-hover-filter,brightness(1.06))!important;}ha-card:hover::after{background:var(--sc-hover-tint,rgba(255,255,255,0.06))!important;}}ha-card::before{display:none!important;}ha-card::after{content:""!important;position:absolute!important;inset:0!important;border-radius:inherit!important;background:transparent!important;transition:background var(--hemma-popup-tile-hover-duration,0.2s) ease!important;pointer-events:none!important;}ha-ripple{display:none!important;}div#img-cell{position:relative!important;overflow:hidden!important;}div#img-cell::before{display:none!important;}ha-icon{--mdc-icon-size:22px!important;color:var(--sc-clr,#ffffff)!important;}#img-cell img{width:60%!important;height:60%!important;object-fit:contain!important;}' + maskCss,
            styles: {
              card: card,
              grid: [
                { 'grid-template-areas': '"i n"' },
                { 'grid-template-columns': 'auto minmax(0, 1fr)' },
                { 'column-gap': '10px' },
                { 'align-items': 'center' },
              ],
              img_cell: [
                { background: '[[[ ' + act + ' return _sca?"var(--hemma-color-yellow,#FFCC00)":"var(--hemma-scene-icon-off, rgba(255,255,255,0.10))"; ]]]' },
                { 'border-radius': '50%' },
                { width: '38px' },
                { height: '38px' },
                { 'min-width': '38px' },
                { display: 'flex' },
                { 'align-items': 'center' },
                { 'justify-content': 'center' },
                { 'align-self': 'center' },
              ],
              entity_picture: [{ width: '60%' }, { height: '60%' }, { 'object-fit': 'contain' }],
              name: [
                { 'font-size': '14px' },
                { 'font-weight': '500' },
                { color: 'var(--sc-nc)' },
                { 'text-align': 'left' },
                { 'justify-self': 'start' },
                { 'align-self': 'center' },
                { 'line-height': '1.2' },
                { overflow: 'hidden' },
                { 'text-overflow': 'ellipsis' },
                { 'white-space': 'nowrap' },
              ],
            },
          };
        },

        apply(sceneId, transition, sid) {
          const h = liveHass();
          if (!h) return;
          const t = transition == null ? 4 : transition;
          const settle = settleMs(t);
          optimistic = { id: sceneId, until: Date.now() + settle + 750 };
          userTapped = true;
          tapSurface = sid == null ? null : sid;
          sortNotBefore = Date.now() + t * 1000 + 400;
          h.callService('scene', 'turn_on', { entity_id: sceneId, transition: t });
          setTimeout(() => learn(sceneId), settle);
        },

        debug() {
          return { apiDead, noCfg: Array.from(noCfg), cached: Object.keys(cfgCache), ignore };
        },

        surfaceId(key) { return surfaceOf(key).id; },

        frozenHtml(key) {
          const su = surfaces.get(key || 'default');
          return (su && su.freezeUntil > Date.now() && su.html) ? su.html : null;
        },

        noteHtml(key, h) { surfaceOf(key).html = h; },

        sortDebug() {
          return 'v=' + window._hemmaSCv + ' flips=' + flipStat.runs + ' moved=' + flipStat.moved
            + ' skipped=' + (flipStat.skipped || 'none')
            + ' firstSort=' + firstSort + ' userTapped=' + userTapped
            + ' waitLeft=' + Math.max(0, sortNotBefore - Date.now())
            + ' chips=' + flipStat.chips + ' frozen=' + flipStat.frozen
            + ' stores=[' + flipStat.stores.join(',') + ']'
            + ' held=[' + (heldActive || []).join(',') + ']';
        },
      };
    }

    if (!window._hemmaSCTap) {
      window._hemmaSCTap = true;
      document.addEventListener('ll-custom', (e) => {
        const d = (e.detail && e.detail.event_data) ? e.detail.event_data : (e.detail || {});
        if (!d.hemma_scene_tap) return;
        window._hemmaSC.apply(d.hemma_scene_tap, d.hemma_scene_transition);
      });
    }
    return true;
  ]]]

custom_fields.sc_init:
[[[
  try {
    const host = this.getRootNode && this.getRootNode().host;
    if (host && typeof window._hemmaSCReg === 'function') window._hemmaSCReg(host);
    const rail = host && host.shadowRoot ? host.shadowRoot.getElementById('scenes_row') : null;
    if (rail && window._hemmaSC && window._hemmaSC.flip) {
      if (!rail._scBusyBound) {
        rail._scBusyBound = true;
        rail.addEventListener('scroll', () => { window._hemmaSCBusy = Date.now(); }, { passive: true });
      }
      requestAnimationFrame(() => { try { window._hemmaSC.flip(rail); } catch (_) {} });
    }
  } catch (_) {}
  return '';
]]]

menu_has_ha.value:
[[[
  if (!window._hemmaMenuHA) { window._hemmaMenuHA = true; window.dispatchEvent(new Event('hemma-menu-ha')); }
  return true;
]]]

tap_action.javascript:
[[[
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const OPEN = 'hemma-settings-menu';
  const gone = document.querySelector('.' + OPEN);
  if (gone) { if (gone._close) gone._close(); return; }

  const host = this;
  const PHONE = window.matchMedia(
    '(max-width: 767px), (max-height: 500px)').matches;
  const CAPSULE = getComputedStyle(host).getPropertyValue('--hemma-chrome-capsule').trim() === '1';
  const lift = function (on) {
    if (PHONE || CAPSULE) return;
    if (on) {
      host.style.setProperty('--hemma-settings-fill', '#fff');
      host.style.setProperty('--hemma-settings-ink', '#1c1c20');
    } else {
      host.style.removeProperty('--hemma-settings-fill');
      host.style.removeProperty('--hemma-settings-ink');
    }
  };
  lift(true);

  const card = host.shadowRoot && host.shadowRoot.querySelector('ha-card');
  let r = (card || host).getBoundingClientRect();
  const r0 = r;
  for (let up = host, i = 0; up && i < 6; i++) {
    const rootNode = up.getRootNode && up.getRootNode();
    up = rootNode && rootNode.host;
    const tpl = up && up._config && up._config.template;
    if (tpl && [].concat(tpl).indexOf('hemma_mobile_chrome') >= 0) {
      const cap = up.shadowRoot && up.shadowRoot.querySelector('ha-card');
      if (cap) r = cap.getBoundingClientRect();
      break;
    }
    if (CAPSULE && tpl && [].concat(tpl).indexOf('hemma_room') >= 0) {
      const cap = up.shadowRoot && up.shadowRoot.querySelector('#chrome_pill');
      if (cap && cap.getBoundingClientRect().width) r = cap.getBoundingClientRect();
      break;
    }
  }

  // document.body, or button-card's .ellipsis wrapper clips it.
  const menu = document.createElement('div');
  menu.className = OPEN;
  menu.setAttribute('role', 'menu');
  Object.assign(menu.style, {
    position: 'fixed', zIndex: '99999', padding: '6px', minWidth: '168px',
    boxSizing: 'border-box',
  });
  if (window.hemmaMenuGlass) {
    window.hemmaMenuGlass.apply(menu);
    if (window.hemmaMenuGlass.lockScroll) window.hemmaMenuGlass.lockScroll(menu);
  }

  let overflowAssist = false;
  if (variables.assist_available) {
    for (let up = host, i = 0; up && i < 6; i++) {
      const rn = up.getRootNode && up.getRootNode();
      up = rn && rn.host;
      const t = up && up._config && up._config.template;
      if (t && [].concat(t).indexOf('hemma_room') >= 0) {
        const slot = up.shadowRoot && up.shadowRoot.getElementById('assist');
        try {
          overflowAssist = !!slot && getComputedStyle(slot).display === 'none';
        } catch (e) {}
        break;
      }
    }
  }

  const ITEMS = [
    { label: L('ui.common.refresh', 'Refresh'), glyph: 'refresh',
      run: function () { window.location.reload(); } },
    { label: L('ui.panel.lovelace.menu.configure_ui', 'Edit dashboard'), glyph: 'pencil', run: function () {
      const seg = (window.location.pathname || '').split('/').filter(Boolean);
      const view = seg.length > 1 ? seg[1] : '';
      const dash = seg.length ? seg[0] : '';
      // Must match PANEL_URL in custom_components/hemma/const.py
      window.location.assign('/hemma-studio' + (view ? '/' + view : '')
        + (dash ? '?dash=' + encodeURIComponent(dash) : ''));
    } },
  ];
  // A YAML dashboard isn't Hemma Studio's to edit.
  if (variables.hemma_ui_managed === false) ITEMS.splice(1, 1);

  // Hemma hides HA's own menu button; on a tablet or desktop this is the way back to it.
  if (!PHONE) {
    ITEMS.push({ label: T('nav.home_assistant', 'Home Assistant'), icon: 'mdi:home-assistant', run: function () {
      // Overview's buttons live in hemma-nav-bar on <body>, outside HA, so the event must start from the nav.
      const nav = document.querySelector('hemma-nav-bar');
      if (nav && nav._openHaMenu) nav._openHaMenu();
      else host.dispatchEvent(new Event('hass-toggle-menu', { bubbles: true, composed: true }));
    } });
  }

  if (overflowAssist) {
    ITEMS.unshift({ label: T('menu.assist', 'Assist'), glyph: 'assist-fill', run: function () {
      const root = document.querySelector('home-assistant') || host;
      root.dispatchEvent(new CustomEvent('hass-action', {
        bubbles: true, composed: true,
        detail: { config: { tap_action: { action: 'assist' } }, action: 'tap' },
      }));
    } });
  }

  const mkItem = function (spec) {
  const item = document.createElement('button');
  item.type = 'button';
  item.setAttribute('role', 'menuitem');
  Object.assign(item.style, {
    display: 'flex', alignItems: 'center', gap: '14px',
    width: '100%', textAlign: 'left', border: '0',
    background: 'transparent', color: 'var(--hemma-menu-ink, #fff)', font: 'inherit',
    fontSize: '14px', fontWeight: '500', letterSpacing: '-0.01em',
    lineHeight: '1.35', padding: '9px 13px',
    // Concentric: the panel's radius less the 6px it sits inside.
    borderRadius: 'calc(var(--hemma-menu-radius, 28px) - 6px)',
    cursor: 'default', outline: 'none'
  });
  const gl = document.createElement(spec.glyph ? 'span' : 'ha-icon');
  if (spec.glyph) {
    const u = (typeof window.hemmaIconUrl === 'function'
      ? window.hemmaIconUrl(spec.glyph)
      : '/hemma_assets/icons/' + spec.glyph + '.svg');
    gl.style.background = 'var(--hemma-menu-ink, rgba(255,255,255,0.92))';
    gl.style.setProperty('-webkit-mask', 'url("' + u + '") no-repeat center / contain');
    gl.style.setProperty('mask', 'url("' + u + '") no-repeat center / contain');
  } else {
    gl.setAttribute('icon', spec.icon);
  }
  Object.assign(gl.style, {
    width: '21px', height: '21px',
    color: 'var(--hemma-menu-ink, rgba(255,255,255,0.92))', flex: 'none',
  });
  // A custom property never lands through Object.assign.
  gl.style.setProperty('--mdc-icon-size', '21px');
  const tx = document.createElement('span');
  tx.textContent = spec.label;
  tx.style.whiteSpace = 'nowrap';
  item.appendChild(gl);
  item.appendChild(tx);
  const lit = function (on) {
    item.style.background = on ? 'var(--hemma-menu-lit, rgba(255,255,255,0.18))' : 'transparent';
  };
  item.onmouseenter = function () { lit(true); };
  item.onmouseleave = function () { lit(false); };
  item.onfocus = function () { lit(true); };
  item.onblur = function () { lit(false); };
  item.onclick = function () { menu._close(); spec.run(); };
  return item;
  };

  ITEMS.forEach(function (spec) { menu.appendChild(mkItem(spec)); });
  document.body.appendChild(menu);

  const w = menu.offsetWidth;
  menu.style.top = (CAPSULE ? Math.round(r0.top + 49)
    : window.hemmaMenuGlass && window.hemmaMenuGlass.dropTop
      ? window.hemmaMenuGlass.dropTop(r, 10)
      : Math.round(r.bottom + 10)) + 'px';
  menu.style.left = Math.round(Math.max(12, Math.min(r.right - w, window.innerWidth - w - 12))) + 'px';
  if (window.hemmaMenuGlass) window.hemmaMenuGlass.enter(menu);

  const yielded = [];
  if (window.innerWidth >= 768) {
    const mt = parseFloat(menu.style.top) || 0, ml = parseFloat(menu.style.left) || 0;
    const mb = { top: mt, left: ml, bottom: mt + menu.offsetHeight, right: ml + w };
    for (let up = host, i = 0; up && i < 8; i++) {
      const rn = up.getRootNode && up.getRootNode();
      const nps = rn && rn.querySelectorAll ? rn.querySelectorAll('#now_playing') : [];
      if (nps.length) {
        nps.forEach(function (np) {
          const bc = np.querySelector('button-card'), el = (bc && bc.shadowRoot && bc.shadowRoot.querySelector('#np_main')) || np;
          const q = el.getBoundingClientRect();
          if (!el.animate || !q.width || q.bottom < mb.top || q.top > mb.bottom || q.right < mb.left || q.left > mb.right) return;
          yielded.push(el.animate([{ opacity: 1, filter: 'blur(0px)' }, { opacity: 0.3, filter: 'blur(10px)' }], { duration: 320, easing: 'cubic-bezier(0.32, 0.72, 0, 1)', fill: 'forwards' }));
        });
        break;
      }
      up = rn && rn.host;
    }
  }

  const onKey = function (e) { if (e.key === 'Escape') menu._close(); };
  const onAway = function (e) {
    const t = e.composedPath ? e.composedPath()[0] : e.target;
    if (!menu.contains(t)) menu._close();
  };
  menu._close = function () {
    lift(false);
    yielded.splice(0).forEach(function (an) { const done = function () { an.cancel(); }; an.reverse(); an.finished.then(done, done); });
    window.removeEventListener('keydown', onKey, true);
    document.removeEventListener('pointerdown', onAway, true);
    window.removeEventListener('scroll', menu._close, true);
    window.removeEventListener('resize', menu._close);
    if (window.hemmaMenuGlass) {
      window.hemmaMenuGlass.exit(menu, function () {
        if (menu.parentNode) menu.remove();
      });
    } else if (menu.parentNode) { menu.remove(); }
  };

  setTimeout(function () {
    window.addEventListener('keydown', onKey, true);
    document.addEventListener('pointerdown', onAway, true);
    window.addEventListener('scroll', menu._close, true);
    window.addEventListener('resize', menu._close);
  }, 0);
]]]

