hemma_shared.extra_styles:
[[[
  const rooms = variables.preload_rooms || [];
  const suffix = variables.preload_night_suffix || '-night';
  const basePath = variables.preload_path || '/hemma_assets/rooms';
  const ext = variables.preload_extension || '.jpg';

  const isDark =
    typeof hass?.themes?.darkMode === 'boolean'
      ? hass.themes.darkMode
      : window.matchMedia('(prefers-color-scheme: dark)').matches;

  // Keyed so a dark-mode switch re-warms the other variant and releases the previous one.
  const preloadKey = (isDark ? 'night' : 'day') + '|' + rooms.join(',');

  if (window.hemmaPreloadKey !== preloadKey) {
    window.hemmaPreloadKey = preloadKey;
    window.hemmaPreloadedImages = [];

    const warm = (src) => {
      const img = new Image();
      img.decoding = 'async';
      if ('fetchPriority' in img) img.fetchPriority = 'low';
      img.src = src;
      window.hemmaPreloadedImages.push(img);
      return (img.decode ? img.decode() : Promise.resolve()).catch(() => {});
    };

    // One at a time on idle, so warming other rooms never competes with the current paint.
    const queue = rooms.map(r => `${basePath}/${r}${isDark ? suffix : ''}${ext}`);
    const idle = window.requestIdleCallback
      ? (fn) => window.requestIdleCallback(fn, { timeout: 500 })
      : (fn) => setTimeout(fn, 300);
    const step = () => {
      const next = queue.shift();
      if (next) warm(next).then(() => idle(step));
    };
    idle(step);
  }

  return `

:host{
  position: relative;
  z-index: 0;

  --hero-gutter: var(--content-rail,
                  var(--hemma-rail-left,
                  var(--page-gutter, 8vw)));
  --hero-top: var(--header-top-desktop, clamp(220px, 26vh, 340px));
  --hero-temp-font-size: var(--hero-temp-font-size-desktop, 18px);
  --hero-temp-font-weight: 600;
  --hero-temp-letter-spacing: 0.04em;
  --hero-temp-reserve: calc(var(--hero-temp-font-size) * 1.2);
  /* Read by hemma_room as the weather widget's own height, which it subtracts to
     bottom-anchor the block. Must track the real height or the widget drifts down
     into the room name as the weather scales. 48px at the 10px floor. */
  --hero-weather-hero-height: calc(var(--hemma-u-weather, 10px) * 4.8);
  --hero-header-gap-current: var(--hero-header-gap-desktop, 6px);
  --hero-img-blur-current: var(--hemma-hv-blur, var(--hero-img-blur, 4px)) !important;
  --hero-img-scale-current: var(--hero-img-scale, 1.08);
  --hero-img-filter: blur(var(--hero-img-blur-current))
    saturate(var(--hero-img-saturate, 1.02))
    brightness(var(--hero-img-brightness, .985));
  --hero-img-filter-from: blur(var(--hero-img-blur-current))
    saturate(var(--hero-img-saturate-from, 1.0))
    brightness(var(--hero-img-brightness-from, .97));
  --hemma-hover-filter: none !important;
  --hemma-card-hover-filter: none !important;
  --hemma-card-hover-shadow: none !important;
  -webkit-tap-highlight-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}

:host ha-card{
  position: relative;
  pointer-events: auto !important;
  cursor: default !important;
  filter: none !important;
  opacity: 1 !important;
  transform: none !important;
  box-shadow: none !important;
  --ha-card-box-shadow: none !important;
  transition: none !important;
  -webkit-tap-highlight-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: center center, center center !important;
  background-size: cover, cover !important;
  background-attachment: local, local !important;
  isolation: isolate !important;
  overflow-x: hidden !important;
  overflow-y: hidden !important;
}

