/* Background image */
:host ha-card::after{
  content:"";
  position:absolute;
  inset:0;
  border-radius:inherit;
  pointer-events:none;
  z-index:-10;
  background-image: var(--hemma-ov-photo,
    linear-gradient(var(--hero-tint, rgba(55,55,55,0.50)), var(--hero-tint, rgba(55,55,55,0.50))),
