  animation: hemmaRoomParallax var(--hemma-hero-anim-dur, 0.5s)
    var(--hemma-hero-anim-delay, 0.05s) cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}

@keyframes hemmaRoomParallax {
