date_fit.value:
[[[
  const el = this;
  if (!el._hemmaDateFit) {
    el._hemmaDateFit = () => {
      const sp = el.shadowRoot && el.shadowRoot.querySelector('.hemma-date, .hemma-twx');
      if (!sp || !sp.parentElement) { el.removeAttribute('data-date-hidden'); return; }
      el.removeAttribute('data-date-hidden');
      const edge = window._hemmaNavEdge;
      const box = sp.parentElement.getBoundingClientRect();
      const span = window._hemmaNavSpan;
      const sameRow = !span || (box.bottom > span[0] && box.top < span[1]);
      if (typeof edge === 'number' && sameRow && box.right > edge - 24) el.setAttribute('data-date-hidden', '');
    };
    window.addEventListener('hemma-nav-edge', () => el._hemmaDateFit());
    window.addEventListener('resize', () => requestAnimationFrame(() => el._hemmaDateFit()));
  }
  requestAnimationFrame(() => el._hemmaDateFit());
  return true;
]]]

hemma_time.name:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  const id  = variables.time_entity || "sensor.time";
  const ent = states[id];
  if (!ent) return "";

  const raw    = String(ent.state || "");
  const use12  = variables.use_12h === true;
  const suffix = (variables.time_suffix || "").toString().trim();

  const to12h = (timeStr) => {
    const m = String(timeStr).match(/^(\d{1,2}):(\d{2})$/);
    if (!m) return timeStr;
    let h = parseInt(m[1], 10);
    const min = m[2];
    const ampm = h >= 12 ? T('time.pm', 'PM') : T('time.am', 'AM');
    h = h % 12;
    if (h === 0) h = 12;
    return `${h}:${min} ${ampm}`;
  };

  let timePart = raw;
  if (raw.includes(",")) {
    const parts = raw.split(",");
    timePart = (parts[1] || "").trim() || raw;
  }

  let display = timePart;
  if (use12 && /^\d{1,2}:\d{2}$/.test(timePart)) {
    display = to12h(timePart);
  }

  if (suffix) display = `${display} ${suffix}`;
  display = display.toUpperCase();
  const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;');
  let out = esc(display);
  if (variables.show_date === true && window.hemmaDate) {
    const date = window.hemmaDate(hass, variables.date_style === 'long' ? 'long' : 'short');
    if (date) out += '<span class="hemma-date">' + esc(date) + '</span>';
  }
  if (variables.show_weather === true && variables.weather_entity) {
    const w = states[variables.weather_entity];
    let deg = null;
    const t = variables.weather_temp_sensor && states[variables.weather_temp_sensor];
    if (t && Number.isFinite(Number(t.state)) && t.state !== '') deg = Math.round(Number(t.state));
    if (deg === null && w && Number.isFinite(Number(w.attributes.temperature))) deg = Math.round(Number(w.attributes.temperature));
    let unit = '';
    if (variables.show_temp_unit === true) {
      const u = (t && t.attributes.unit_of_measurement) || (w && w.attributes.temperature_unit) || hass.config?.unit_system?.temperature || '';
      unit = esc(String(u).replace('°', '').trim());
    }
    if (deg !== null) out += '<span class="hemma-twx">' + deg + '°' + (unit ? '&nbsp;' + unit : '') + '</span>';
  }
  return out;
]]]

