hemma_weather.name:
[[[
  let tempVal = null;

  const tempEid = variables.weather_temp_sensor;
  const w = entity;

  if (tempEid) {
    const tState = states[tempEid];
    if (tState && !['unknown','unavailable',''].includes(String(tState.state))) {
      const n = Number(tState.state);
      if (!Number.isNaN(n)) tempVal = Math.round(n);
    }
  }

  if (tempVal === null) {
    const n = Number(w?.attributes?.temperature);
    if (!Number.isNaN(n)) tempVal = Math.round(n);
  }

  if (variables?.hero_mode) {
    const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;');
    if (variables?.hero_line === 'date') {
      const date = window.hemmaDate ? window.hemmaDate(hass, variables?.date_style === 'short' ? 'short' : 'long') : '';
      return date ? `<div style="font-size:1em;font-weight:500;letter-spacing:0;line-height:1.25;opacity:0.72;">${esc(date)}</div>` : '';
    }
    const both = variables?.hero_line === 'both';
    const bdate = both && window.hemmaDate ? window.hemmaDate(hass, variables?.date_style === 'long' ? 'long' : 'short') : '';
    const lead = bdate ? `<span style="font-weight:500;opacity:0.72;">${esc(bdate)}</span><span style="opacity:0.5;margin:0 6px;">·</span>` : '';
    if (tempVal === null) return bdate ? `<div style="font-size:1em;font-weight:500;line-height:1.25;opacity:0.72;">${esc(bdate)}</div>` : '';

    let iconHtml = '';
    const shows = variables?.conditions || '';
    if (variables?.show_icon !== false && shows === '') {
      const condRaw = String(w?.state || '').toLowerCase();
      const svgMap = {
        'sunny':           'clear-day',
        'clear-night':     'clear-night',
        'partlycloudy':    'partly-cloudy-day',
        'cloudy':          'cloudy',
        'overcast':        'cloudy',
        'rainy':           'rain',
        'pouring':         'rain-heavy',
        'snowy':           'snow',
        'snow':            'snow',
        'snowy-rainy':     'weather-mixed',
        'hail':            'rain-heavy',
        'lightning':       'thunder',
        'lightning-rainy': 'lightning-rainy',
        'fog':             'fog',
        'windy':           'wind',
        'windy-variant':   'wind',
        'exceptional':     'weather-mixed'
      };
      const file = svgMap[condRaw];
      if (file) {
        iconHtml = `<img src="/hemma_assets/weather/${file}-fill.svg?v=2" style="width:auto;height:calc(var(--weather-icon-size,34px) * 0.68);object-fit:contain;opacity:0.92;flex-shrink:0;filter:var(--hv-wx-filter, none);" />`;
      }
    }

    let cond = '';
    const condKey = String(w?.state || '').toLowerCase().trim();
    if (shows === 'text' && condKey && !['unknown', 'unavailable'].includes(condKey)) {
      const loc = hass?.localize ? hass.localize(`component.weather.entity_component._.state.${condKey}`) : '';
      cond = (loc && !loc.includes('entity_component')) ? loc
        : condKey.replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    }
    const condHtml = cond ? `<span style="position:relative;top:var(--weather-hero-digit-align, 3px);font-weight:600;margin-left:4px;">${esc(cond)}</span>` : '';
    let unit = '';
    if (variables?.show_temp_unit === true) {
      const ts = tempEid ? states[tempEid] : null;
      unit = String((ts && ts.attributes.unit_of_measurement) || w?.attributes?.temperature_unit || hass.config?.unit_system?.temperature || '').replace('°', '').trim();
    }
    return `<span style="display:inline-flex;align-items:center;gap:4px;">${lead}<span style="position:relative;top:var(--weather-hero-digit-align, 3px);">${tempVal}°${unit ? '&nbsp;' + esc(unit) : ''}</span>${iconHtml}${condHtml}</span>`;
  }

  return (tempVal === null) ? '' : `${tempVal}°`;
]]]

