card.--bg-url:
[[[
  const cacheKey = '_hemmaMediaBgUrl';
  const a = entity?.attributes || {};
  const pref = a.entity_picture_local || a.entity_picture || a.media_image_url;

  if (pref) {
    const url = String(pref).startsWith('/') ? `${location.origin}${pref}` : pref;
    if (this._hemmaBgRawUrl !== url) {
      this._hemmaBgRawUrl = url;
      const img = new Image();
      img.onload = () => {
        if (this._hemmaBgRawUrl !== url) return;
        const wrapped = `url("${url}")`;
        this[cacheKey] = wrapped;
        const card = this.shadowRoot?.querySelector('ha-card');
        if (card) { card.style.setProperty('--bg-url', wrapped);
                     card.style.setProperty('--hemma-badge-has-art', '1'); }
        this.requestUpdate?.();
      };
      img.src = url;
    }
  }
  return this[cacheKey] || 'none';
]]]

