  const st      = stRaw.toLowerCase();
  const hide    = !enabled || !hasEnt || !stRaw || ['unknown','unavailable','none'].includes(st);

  const aqLevel = (() => { const st0 = String(entity?.state ?? '').trim().toLowerCase(); const base = { excellent: 0, good: 0.5, moderate: 1, fair: 1, poor: 2, bad: 3, 'very bad': 3, 'very poor': 3 }[st0]; const sns = Array.isArray(variables?.sensors) ? variables.sensors.filter(Boolean) : []; let worst = -1; sns.forEach((eid) => { const n = parseFloat(states[eid]?.state); if (isNaN(n)) return; const id = eid.toLowerCase(); const a = states[eid]?.attributes || {}; const dc = String(a.device_class || '').toLowerCase(); const idx = id.endsWith('_index') || String(a.unit_of_measurement || '').toLowerCase() === 'index'; const t = (id.includes('pm25') || id.includes('pm2_5') || dc === 'pm25') ? [12, 35.4, 55.4] : (id.includes('pm10') || dc === 'pm10') ? [54, 154, 254] : (id.includes('voc') || id.includes('volatile_organic') || dc.includes('volatile_organic')) ? (idx ? [6, 8, 9] : [100, 200, 300]) : (id.includes('no2') || id.includes('nitrogen_dioxide') || dc === 'nitrogen_dioxide') ? (idx ? [6, 8, 9] : [53, 100, 360]) : (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide') ? [1000, 1500, 2000] : null; if (!t) { worst = Math.max(worst, 0); return; } worst = Math.max(worst, n <= t[0] ? 0 : n <= t[1] ? 1 : n <= t[2] ? 2 : 3); }); return worst >= 0 ? worst : base; })();
