hemma_badge_energy.name:
[[[
  const T = window._hemmaT || ((k, en, v) => String(en).replace(/\{(\w+)\}/g,
    (m, p) => (v && Object.prototype.hasOwnProperty.call(v, p) ? String(v[p]) : m)));
  const esc = (t) => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  const title = variables?.label
    || entity?.attributes?.friendly_name
    || T('energy.power', 'Power');

  const cur = String((typeof hass !== 'undefined' && hass?.config?.currency) || 'USD').toUpperCase();
  const SYM = { USD:'$', CAD:'$', AUD:'$', NZD:'$', MXN:'$',
                EUR:'\u20AC', GBP:'\u00A3', JPY:'\u00A5', CNY:'\u00A5',
                SEK:'kr', NOK:'kr', DKK:'kr', CHF:'Fr', INR:'\u20B9',
                BRL:'R$', PLN:'z\u0142', KRW:'\u20A9' }[cur] || '$';
  const NUM = window.hemmaNum || ((v, a, b) => Number(v).toFixed(b ?? a ?? 0));
  const money = (n) => window.hemmaMoney ? window.hemmaMoney(n, cur)
    : SYM + (n >= 100 ? Math.round(n) : n.toFixed(2));

  const resolveUnit = (u, e) => {
    u = String(u || 'auto').toLowerCase();
    if (u === 'energy') return 'kwh';
    if (u !== 'auto' && u !== '') return u;
    const dc = String(e?.attributes?.device_class || '').toLowerCase();
    const uom = String(e?.attributes?.unit_of_measurement || '');
    if (dc === 'monetary') return 'cost';
    if (dc === 'energy' || /^k?Wh$/i.test(uom)) return 'kwh';
    return 'auto';
  };

  const raw = parseFloat(entity?.state);
  const unit = resolveUnit(variables?.unit, entity);
  let value = '';
  if (Number.isFinite(raw)) {
    if (unit === 'kwh') {
      value = (raw >= 10 ? NUM(Math.round(raw), 0, 0) : NUM(raw, 1, 1)) + ' kWh';
    } else if (unit === 'cost') {
      value = money(raw);
    } else {
      value = raw >= 1000 ? NUM(raw / 1000, 1, 1) + ' kW' : NUM(Math.round(raw), 0, 0) + ' W';
    }
  }

  const cid = variables?.cost_entity;
  const cost = cid ? parseFloat(states[cid]?.state) : NaN;
  if (Number.isFinite(cost)) {
    value = value ? (value + ' · ' + money(cost)) : money(cost);
  }

  return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      ${value ? `<div class="badge-sub">${esc(value)}</div>` : ''}
    </div>
  `;
]]]

