card.transition:
[[[
  if (!this._hemmaMediaGroupMountTime) this._hemmaMediaGroupMountTime = Date.now();
  if (Date.now() - this._hemmaMediaGroupMountTime < 400) return 'none';
  return 'background-color .22s ease, box-shadow .24s ease, transform .24s ease, filter .18s ease, opacity .35s ease';
