card.--bg-url:
[[[
  const cacheKey = '_hemmaPlexBgUrl';
  const sid = variables?.session_entity;
  const a = (sid && hass.states[sid]?.attributes) || {};
  const raw =
    a.image_url ||
    a.entity_picture_local ||
    a.entity_picture ||
    a.media_image_url;

  if (raw) {
    const url = String(raw).startsWith('/') ? `${location.origin}${raw}` : raw;
    let clean = url;
    try {
      const parsed = new URL(url, location.origin);
      // authSig signs the exact param list, so editing the query of a signed URL 401s it.
      if (!parsed.searchParams.has('authSig')) {
        parsed.searchParams.delete('refresh');
        clean = parsed.toString();
      }
    } catch (e) {}
    if (this._hemmaBgRawUrl !== clean) {
      this._hemmaBgRawUrl = clean;
      const img = new Image();
      img.onload = () => {
        if (this._hemmaBgRawUrl !== clean) return;
        const wrapped = `url("${clean}")`;
        this[cacheKey] = wrapped;
        const card = this.shadowRoot?.querySelector('ha-card');
        if (card) { card.style.setProperty('--bg-url', wrapped);
                     card.style.setProperty('--hemma-badge-has-art', '1'); }
        this.requestUpdate?.();
      };
      img.src = clean;
    }
  }
  return this[cacheKey] || 'none';
]]]

