    !['false','0','no','off','disabled'].includes(String(v).trim().toLowerCase());
  const st = String(entity?.state ?? '').trim().toLowerCase();
  const dead = !entity?.entity_id || !st || ['unknown','unavailable'].includes(st);

  const dom = String(entity?.entity_id || '').split('.')[0];
  const dc = String(entity?.attributes?.device_class || '').toLowerCase();
  const isDoor = dc === 'door' || dc === 'opening';
  let name = 'lock';
  if (dom === 'camera') name = 'doorbell';
  else if (dom === 'lock') name = st === 'locked' ? 'lock-fill' : 'lock-open-fill';
  else if (dom === 'binary_sensor' || dom === 'cover') {
