  const unit = String(variables?.temp_unit || 'F').toUpperCase();
  const t = (unit === 'F')
    ? { cool: 70, warm: 81 }
    : { cool: 21, warm: 27 };

  let svgUrl;
  if      (v <= t.cool) svgUrl = window.hemmaIconUrl('temp-low');
  else if (v <= t.warm) svgUrl = window.hemmaIconUrl('temp-medium');
  else                  svgUrl = window.hemmaIconUrl('temp-high');

  let gaugeCSS = '';
  if (variables?.gauge && !hide) {
    const gf  = Math.max(0.05, Math.min(1,
      unit === 'F' ? (v - 45) / 50 : (v - 7) / 28));
    const arc = Math.round(gf * 270);
    const rr = 13.5, C = 16, W = 3;
    const pt = (deg) => {
      const a = deg * Math.PI / 180;
      return `${(C + rr * Math.sin(a)).toFixed(3)} ${(C - rr * Math.cos(a)).toFixed(3)}`;
    };
    const arcPath = (a0, a1) =>
      `M ${pt(a0)} A ${rr} ${rr} 0 ${(a1 - a0) > 180 ? 1 : 0} 1 ${pt(a1)}`;
    let paths = '';
    if (arc < 269) paths += `<path d='${arcPath(225 + arc, 495)}' stroke='white' stroke-opacity='0.30' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;
    paths += `<path d='${arcPath(225, 225 + arc)}' stroke='white' stroke-width='${W}' stroke-linecap='round' fill='none'/>`;

    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'>${paths}</svg>`;
    const maskUrl = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
    gaugeCSS = `
      #img-cell::before, .img-cell::before {
        background-color: var(--hemma-badge-icon-fg, var(--hemma-icon-color, var(--primary-text-color))) !important;
      }

      #img-cell::after, .img-cell::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 9999px;
        background: var(--hemma-icon-color, #fff);
        -webkit-mask: ${maskUrl} no-repeat center / 100% 100%;
        mask: ${maskUrl} no-repeat center / 100% 100%;
        transform: translateZ(0);
        -webkit-transform: translateZ(0);
      }

      ha-card.button-card-main, ha-card.button-card-main:hover, ha-card.button-card-main:active,
      :host(:hover) ha-card, :host(:active) ha-card {
        background: transparent !important;
        box-shadow: none !important;
        filter: none !important;
        -webkit-filter: none !important;
        -webkit-tap-highlight-color: transparent !important;
      }
      ha-ripple, mwc-ripple { display: none !important; }
    `;
  }

  return `
    :host{display:${hide ? 'none' : 'inline-block'} !important;order:var(--hemma-badge-order-climate,1);}
    #img-cell, .img-cell { position: relative; }
    #img-cell #icon, .img-cell #icon { color: transparent !important; opacity: 0 !important; }
    #img-cell::before, .img-cell::before {
      content: '';
      position: absolute;
      inset: 0;
      background-color: var(--hemma-icon-color, var(--primary-text-color));
      -webkit-mask: url('${svgUrl}') no-repeat center / var(--hemma-badge-icon-scale, 85%) var(--hemma-badge-icon-scale, 85%);
      mask: url('${svgUrl}') no-repeat center / var(--hemma-badge-icon-scale, 85%) var(--hemma-badge-icon-scale, 85%);
      transform: translateZ(0);
    }
  ` + gaugeCSS;
]]]

