hemma_badge_temp.name:
[[[
  const v    = parseFloat(entity?.state);
  const unit = String(variables?.temp_unit || 'F').toUpperCase();
  if (isNaN(v)) return '';

  const t = (unit === 'F')
    ? { veryCold: 65, cool: 70, comfortable: 76, warm: 81, hot: 85 }
    : { veryCold: 18, cool: 21, comfortable: 24, warm: 27, hot: 29 };

  const T = window._hemmaT || ((k, en, v) => String(en).replace(/\{(\w+)\}/g,
    (m, p) => (v && Object.prototype.hasOwnProperty.call(v, p) ? String(v[p]) : m)));
  let label = T('temp.unknown', 'Unknown');
  if      (v <= t.veryCold)    label = T('temp.very_cold', 'Very Cold');
  else if (v <= t.cool)        label = T('temp.cool', 'Cool');
  else if (v <= t.comfortable) label = T('temp.comfortable', 'Comfortable');
  else if (v <= t.warm)        label = T('temp.warm', 'Warm');
  else if (v <= t.hot)         label = T('temp.hot', 'Hot');
  else                         label = T('temp.very_hot', 'Very Hot');

  const dispVal = `${Math.round(v)}°`;
  const esc = (s) => String(s || '').replaceAll('"', '&quot;');

  return `
    <div class="badge-wrap">
      <div class="badge-title">${T('temp.title', 'Temperature')}</div>
      <div class="badge-sub">${esc(label)} · ${dispVal}</div>
    </div>
  `;
]]]

custom_fields.bg_init:
[[[
