  const tx = variables.hemma_hv_text_phone === 'dark' ? '' : (variables.hemma_hv_text_phone || variables.hemma_hv_text);
  if (!window._hemmaHV) window._hemmaHVPending = [variables.hemma_style, isDark, variables.hemma_hv_color, variables.hemma_hv_rest, tx, bd];
  if (variables.hemma_style === 'homeview' && !window._hemmaHV) { document.documentElement.classList.add('hemma-hv'); document.documentElement.classList.toggle('hv-light', !isDark); }
  if (variables.hemma_style === 'homeview' && !window._hemmaHV && !document.getElementById('hemma-hv-cover')) {
    let bg = ''; try { bg = localStorage.getItem('hemma_hv_bg') || ''; } catch (e) {}
    const cov = document.createElement('style');
    cov.id = 'hemma-hv-cover';
    cov.textContent = 'html,body{background:' + (/^[#\w(),.%\s]+$/.test(bg) ? bg : 'var(--primary-background-color)') + ' !important}home-assistant{visibility:hidden !important}';
    document.head.appendChild(cov);
    setTimeout(() => cov.remove(), 6000);
  }
  if (window._hemmaHV) window._hemmaHV.set(variables.hemma_style, isDark, variables.hemma_hv_color, variables.hemma_hv_rest, tx, bd);
  const ID = 'hemma-mobile-hero-src';
  let el = document.getElementById(ID);
  const hvm = variables.hemma_style === 'homeview';
  const base = variables.image;
  if (!base) {
    if (el) el.remove();
    return '';
  }
  const night = variables.image_night || (base + '-night');
  const dir = hvm ? '/hemma_assets/rooms-soft/' : '/hemma_assets/rooms/';
  const v = hvm ? '--hv-m-photo' : '--hemma-mobile-hero-img';
  const q = hvm ? '?v=3' : '';
  const css = ':root{'
    + v + '-day:url("' + dir + base + '.jpg' + q + '") !important;'
    + v + '-night:url("' + dir + night + '.jpg' + q + '") !important;'
    + '}';
  if (!el) {
    el = document.createElement('style');
    el.id = ID;
    document.head.appendChild(el);
  }
  if (el.textContent !== css) el.textContent = css;
  return '';
]]]

