hemma_np_init.value:
[[[
  // hemma-core.js owns the collector - one definition, served by the
  // integration. If it has not loaded, say so once and let the panel
  // draw empty rather than throwing on every template below.
  // Redrawn by core's flush on arrival; otherwise the row waits for the next media update.
  if (typeof window._hemmaNPView !== 'function' && window._hemmaCoreWaiters !== null) {
    (window._hemmaCoreWaiters = window._hemmaCoreWaiters || new Set()).add(this);
  }
  if (typeof window._hemmaNP !== 'function' && !window._hemmaNPNoCore) {
    window._hemmaNPNoCore = 1;
    // Not immediately: a module resource is still loading while the
    // first render evaluates this, so the bare check cried wolf on
    // every cold load and then latched, leaving a stale error in the
    // console for a file that had in fact arrived.
    setTimeout(function () {
      if (typeof window._hemmaNP === 'function') return;
      console.error('Hemma: hemma-core.js has not loaded, so Now Playing '
        + 'cannot collect sources. Check the dashboard resource for it.');
    }, 5000);
  }
  return true;
]]]

hemma_np_subscribe.value:
[[[
  const el = this;
  window._hemmaNPShell = el;
  let anyMissing = false;
  for (let i = 1; i <= 5; i++) {
    const e = variables['media_player_' + i];
    if (e) { if (states[e] === undefined) anyMissing = true; }
  }
  for (let i = 1; i <= 2; i++) {
    const s = variables['plex_stream_' + i];
    if (s && states[s] === undefined) anyMissing = true;
    const p = variables['psn_' + i];
    if (p && states[p] === undefined) anyMissing = true;
  }

  // Retry
  if (anyMissing && !el._npSyncRecheckScheduled) {
    el._npSyncRecheckScheduled = true;
    setTimeout(() => {
      try {
        const h = el._hass || el.hass;
        if (h) el.hass = Object.assign({}, h);
        if (typeof el.requestUpdate === 'function') el.requestUpdate('_config', undefined);
      } catch (e) {}
    }, 1500);
  }

  for (let i = 1; i <= 5; i++) {
    const e = variables['media_player_' + i];
    if (e) states[e];
  }
  for (let i = 1; i <= 2; i++) {
    const s = variables['plex_stream_' + i];
    if (s) states[s];
    const p = variables['psn_' + i];
    if (p) states[p];
  }
  // Touch the Discord entities so button-card tracks them too - without this the
  // row would only pick up a game starting or stopping on some unrelated render.
  for (const k of ['discord_user', 'discord_online', 'discord_game', 'discord_details',
                   'discord_image', 'steam_account', 'steam_online', 'steam_game', 'steam_image']) {
    const e = variables[k];
    if (e) states[e];
  }

  // ── Departure recheck ────────────────────────────────────────────
  const rawList = (typeof window._hemmaNP === 'function')
    ? window._hemmaNP(states, variables.cfg) : [];
  const liveKeys = new Set(rawList.map((x) => x && x.key).filter(Boolean));
  let anyStale = false;
  for (let i = 1; i <= 9; i++) {
    const h = window._hemmaNPSlotState?.['media' + i]?._npHoldSrc;
    if (h && !liveKeys.has(h.key)) { anyStale = true; break; }
  }
  if (anyStale) {
    try { clearTimeout(el._npDepartTimer); } catch (e) {}
    el._npDepartTimer = setTimeout(() => {
      try {
        const h = el._hass || el.hass;
        if (h) el.hass = Object.assign({}, h);
        if (typeof el.requestUpdate === 'function') el.requestUpdate('_config', undefined);
      } catch (e) {}
    }, 1000);
  }

  return true;
]]]

hemma_mobile_now_playing.extra_styles:
[[[
  const staticCSS = `:host(.hemma-navbar-card.hemma-navbar-card):active{filter:none!important;-webkit-filter:none!important}:host{position:sticky!important;top:-9999px!important;filter:none!important;-webkit-filter:none!important}#aspect-ratio{display:block!important;min-width:0!important;min-height:0!important}ha-card.button-card-main{background:transparent!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;box-shadow:none!important;border:none!important;overflow:visible!important;padding:0!important;contain:none!important;isolation:auto!important;will-change:auto!important;transition:none!important}.button-card-main,.button-card-content,#customfields{overflow:visible!important;contain:none!important;isolation:auto!important}#media_row::-webkit-scrollbar{display:none!important}`;
  const npCSS = `
    #media_row > * {
      width: 100% !important;
      min-width: 100% !important;
      max-width: 100% !important;
      flex: 0 0 100% !important;
      scroll-snap-align: start;
      scroll-snap-stop: always;
      box-sizing: border-box !important;
      --np-bloom-strength: 0.62;
    }

    #np_rail > * {
      width: 100% !important;
      max-width: 100% !important;
      flex: 1 1 auto !important;
      --np-bloom-strength: 0.62;
    }

    @media (hover: none) and (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
      #np_rail > * {
        width: calc((100vw
          - (max(var(--hemma-measured-safe-left, 0px), var(--hemma-rail-left, 16px))
             + max(env(safe-area-inset-right), var(--hemma-rail-left, 16px)))
          - 60px - var(--np-gap, 10px)) / 2) !important;
        max-width: calc((100vw
          - (max(var(--hemma-measured-safe-left, 0px), var(--hemma-rail-left, 16px))
             + max(env(safe-area-inset-right), var(--hemma-rail-left, 16px)))
          - 60px - var(--np-gap, 10px)) / 2) !important;
      }
    }


  `;

  const npList = (typeof window._hemmaNPView === 'function')
    ? (typeof window._hemmaNPView === "function" ? window._hemmaNPView(states, variables.cfg) : [])
    : [];
  const anyActive = npList.length > 0;
  const shown = anyActive;
  const ov = shown ? 'visible' : 'hidden';
  this.setAttribute('data-hemma-np', '');
  this.toggleAttribute('data-hemma-np-empty', !shown);
  const bindTitle = () => {
    const t = this.shadowRoot && this.shadowRoot.getElementById('np_title');
    if (!t) return false;
    if (t.__npLink) return true;
    t.__npLink = true;
    let sx = 0, sy = 0, last = 0;
    const go = () => {
      if (!this._npTitleLink || Date.now() - last < 600) return;
      last = Date.now();
      this.dispatchEvent(new CustomEvent('ll-custom', { detail: { hemma_filter: 'media' }, bubbles: true, composed: true }));
    };
    t.addEventListener('touchstart', (ev) => {
      const p = ev.touches && ev.touches[0];
      if (p) { sx = p.clientX; sy = p.clientY; }
    }, { passive: true });
    t.addEventListener('touchend', (ev) => {
      const p = ev.changedTouches && ev.changedTouches[0];
      if (p && (Math.abs(p.clientX - sx) > 10 || Math.abs(p.clientY - sy) > 10)) return;
      go();
    });
    t.addEventListener('click', go);
    return true;
  };
  if (!bindTitle()) requestAnimationFrame(() => requestAnimationFrame(bindTitle));

  return staticCSS + npCSS +
    // An even ease in and out for the row, since the page below moves with it; --np-reveal fades the tiles with their glass intact, where opacity here would drop their blur.
    `:host{display:grid!important;overflow:${ov}!important;grid-template-rows:${shown?'1fr':'0fr'}!important;grid-template-columns:minmax(0,1fr)!important;--np-reveal:${shown?'1':'0'};pointer-events:${shown?'auto':'none'};transition:grid-template-rows .4s cubic-bezier(0.45,0,0.55,1) ${shown?'0s':'.04s'},--np-reveal ${shown?'.3s cubic-bezier(0.25,0.1,0.25,1) .1s':'.22s ease-in'}}` +
    `#aspect-ratio{overflow:${ov}!important}` +
    `ha-card.button-card-main{min-height:0!important;overflow:${ov}!important}`;
]]]

