card.extra_styles:
[[[
  const staticCSS = `:host(.hemma-navbar-card.hemma-navbar-card):active{filter:none!important;-webkit-filter:none!important}:host{filter:none!important;-webkit-filter:none!important;touch-action:pan-x!important}ha-card.button-card-main{will-change:auto!important;isolation:auto!important;contain:none!important;transition:none!important;touch-action:pan-x!important}.button-card-main,.button-card-content,#customfields{touch-action:pan-x!important}#media1 > *,#media2 > *,#media3 > *,#media4 > *,#media5 > *,#media6 > *,#media7 > *,#media8 > *,#media9 > *{width:100%!important;min-width:100%!important;max-width:100%!important;flex:1 1 auto!important}`;

  /* Slot width */
  const flipIds = ['media1','media2','media3','media4','media5','media6','media7','media8','media9'];
  const filter = states['input_select.hemma_mobile_filter']?.state ?? 'all';
  const inColumn = filter === 'media';

  /* Toggling the filter re-renders the whole dashboard and blocks the main thread for
     ~200ms (measured: the first rAF after this render lands at +210ms). width/min-width
     are LAYOUT properties, so their transition runs on the main thread and elapses
     entirely inside that jank — by the first painted frame the tile is already at its
     target, which is why the change looked instant no matter what duration was set.
     transform/opacity survive it because they run on the compositor, which is exactly
     why hemma-core's scaleX FLIP appeared to work where this did not.
     So: hold the PREVIOUS geometry through the janky render, then apply the new one on a
     later frame once the thread is free, so the transition actually gets painted. */
  const wantColumn = inColumn;
  if (this._npColumnApplied === undefined) this._npColumnApplied = wantColumn;
  let useColumn = wantColumn;
  if (this._npColumnApplied !== wantColumn) {
    useColumn = this._npColumnApplied;
    if (!this._npColumnPending) {
      this._npColumnPending = true;
      const settle = () => {
        this._npColumnApplied = wantColumn;
        this._npColumnPending = false;
        const targets = [window._hemmaNPRowCard, window._hemmaNPShell]
          .filter((t) => t && t.isConnected);
        for (const t of targets) {
          try {
            const h = t._hass || t.hass;
            if (h) t.hass = Object.assign({}, h);
            if (typeof t.requestUpdate === 'function') t.requestUpdate('_config', undefined);
          } catch (err) {}
        }
      };
      requestAnimationFrame(() => requestAnimationFrame(() => setTimeout(settle, 0)));
    }
  }
  if (typeof window._hemmaNPView === 'function') {
    (typeof window._hemmaNPView === "function" ? window._hemmaNPView(states, variables.cfg) : []);
  }

  const settled = flipIds.map(id => window._hemmaNPSlotState?.[id]?._npHoldSrc || null);

  const liveList = (typeof window._hemmaNPView === "function")
    ? window._hemmaNPView(states, variables.cfg) : [];

  /* Plan first - it owns which slot each source occupies, including a departing one
     held open for its exit. usesPeek below still counts LIVE tiles, so the survivor
     starts expanding to full width on the same render the exit starts. */
  const plan = (typeof window._hemmaNPPlan === "function")
    ? window._hemmaNPPlan(states, variables.cfg) : liveList.slice();
  const planState = (typeof window._hemmaNPStore === 'function')
    ? window._hemmaNPStore(variables.cfg, 'plan') : {};
  /* Slot indices come from the plan's pos map now - a source owns its wrapper, so the
     exit record no longer carries one. */
  const planPos = planState.pos || {};
  const planPending = planState.pending || {};
  const liveN = liveList.filter(Boolean).length;
  const allGone = liveN === 0;
  if (this._npLiveN !== liveN) {
    this._npLiveN = liveN;
    try { window._hemmaNPMobileRecheck?.(states); } catch (e) {}
  }
  /* The last tile out stays put while the row closes around it; a sideways exit would leave the row nothing to collapse. */
  const exitSlots = {};
  if (!allGone) for (const e of (planState.exits || [])) {
    if (planPos[e.key] !== undefined) exitSlots[planPos[e.key]] = true;
  }
  /* First occupied wrapper - the tile the Media view keeps in the row. */
  const headIdx = plan.findIndex((p) => !!p);

  /* ── MEDIA FILTER OPEN SPEED - tune this ── Only the open direction. Closing keeps the
     .46s used by departures and arrivals; opening has to keep pace with the filter view,
     which switches instantly. Below ~0.15s it starts to read as a jump cut. */
  const columnDur = '0.18s';
  /* Spring for the head only. Measured overshoot is 3.7px on its 26px of travel - the
     theme's usual spring gives 0.6px here, which is invisible, because overshoot scales
     with distance and the head barely moves. Reads as the tile reacting to being pushed:
     on open it overshoots outward past full width and settles; on close it dips inward
     past its resting width as the returning tile pushes it. */
  const columnSpring = 'cubic-bezier(0.34, 1.7, 0.5, 1)';
  /* The slot sliding out has less distance to cover and nothing waiting on it, so it
     reads as lagging if it runs at the head's pace — by the time it finishes, the filter
     view and the column beneath have long since settled. Deliberately shorter than
     columnDur; they are adjacent, so the leaver simply clears out sooner. */
  const columnCollapseDur = '0.13s';
  const columnEase = 'cubic-bezier(0.32, 0.72, 0, 1)';

  /* Closing the filter runs through the BASE transition (useColumn is false by then), so
     without this the return journey used the .46s departure timing and felt stiff next to
     the 0.18s open. Latched for 100ms because extra_styles can evaluate more than once
     per render and a plain flag would be consumed by the first pass. */
  if (useColumn) this._npColumnWasOpen = true;
  else if (this._npColumnWasOpen) {
    this._npColumnWasOpen = false;
    this._npColumnCloseAt = Date.now();
  }
  const closingColumn = !useColumn
    && (Date.now() - (this._npColumnCloseAt || 0)) < 100;
  const entering = {};
  plan.forEach((p, i) => { if (p && planPending[p.key]) entering[i] = true; });
  /* Snap applies only on the render that actually changed the assignment. Re-emitting it
     on the cached renders that follow leaves transition:none stuck on the slot. */
  const planGen = planState.gen || 0;
  const snapOn = planState.snapGen !== planGen;
  planState.snapGen = planGen;
  const slotSnapped = snapOn ? (planState.changed || {}) : {};
  const hvOne = !useColumn && filter === 'all';
  const topKey = liveList[0] ? liveList[0].key : null;
  const topIdx = topKey ? plan.findIndex((p) => p && p.key === topKey) : -1;
  const oneIdx = hvOne ? (topIdx >= 0 ? topIdx : headIdx) : -1;
  const usesPeek = !hvOne && !useColumn && (allGone ? plan.filter(Boolean).length : liveN) > 1;
  /* --hemma-measured-safe-left is measured for the LEFT only (smart-row.js), and the
     right gutter was a flat 11px — so in landscape, where the notch/inset sits on the
     right, the tile ran underneath it and got clipped. env() covers the right directly;
     no JS measurement needed. */
  const gutters = `(max(var(--hemma-measured-safe-left, 0px), var(--hemma-rail-left, 16px))`
    + ` + max(env(safe-area-inset-right), var(--hemma-rail-left, 16px)))`;
  const cap = 'var(--np-slot-cap, 100vw)';
  const peekW = `min(calc(100vw - ${gutters} - var(--np-peek, 26px)), ${cap})`;
  const fullW = `min(calc(100vw - ${gutters}), ${cap})`;
  const activeW = usesPeek ? peekW : fullW;
  /* The gap must NOT animate. It is margin-right on every slot, and column mode used to
     drop it to 0 — so while a neighbor was still visibly collapsing, the head's right
     margin was closing at the same time and the two tiles met. Holding it constant
     whenever more than one slot is occupied means the separation is always there and
     the collapsing slot simply carries its own margin down to 0 with its width. */
  const activeGap = (usesPeek || useColumn) ? 'var(--np-gap, 10px)' : '0px';

  const lsAvailExpr = `(100vw - ${gutters} - 60px)`;
  const lsColW = `calc((${lsAvailExpr} - var(--np-gap, 10px)) / 2)`;
  const lsQ = '@media (hover: none) and (pointer: coarse)'
    + ' and (orientation: landscape) and (max-height: 600px)';
  const lsSlots = '#media1, #media2, #media3, #media4, #media5,'
    + ' #media6, #media7, #media8, #media9';

  const curKeys = settled.map(e => e?.key || null);
  const prevKeys = this._npSlotKeys || [];
  const slotKeyChanged = new Set();
  curKeys.forEach((k, i) => { if (prevKeys[i] !== k) slotKeyChanged.add(flipIds[i]); });
  this._npSlotKeys = curKeys;

  const reduceMotion = window.matchMedia
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;


  /* Publish the row card for the plan's release timer, which has no element of its own. */
  if (!this.__npRoot || !this.__npRoot.getElementById
      || !this.__npRoot.getElementById('media1')) {
    const dig0 = (root, depth) => {
      if (!root || depth > 5) return null;
      if (root.getElementById && root.getElementById('media1')) return root;
      const kids = root.querySelectorAll ? root.querySelectorAll('*') : [];
      for (const k of kids) {
        if (k.shadowRoot) {
          const r = dig0(k.shadowRoot, depth + 1);
          if (r) return r;
        }
      }
      return null;
    };
    const r0 = this.shadowRoot ? dig0(this.shadowRoot, 0) : null;
    if (r0) { this.__npRoot = r0; this.__npPath = 'this.shadowRoot > button-card'; }
  }
  if (this.__npRoot && this.__npRoot.host) window._hemmaNPRowCard = this.__npRoot.host;

  /* Rule for a partially visible card: the first tap brings it into view, you act
     on it with the second. Without this, a thumb landing on the 26px peek edge opens
     more-info for a source you can barely see.
     Capture phase on the scroller, because button-card binds its action to touchend/click
     on the tile - capture runs first, so stopPropagation prevents the action ever firing.
     touchstart is deliberately left alone (it is passive, and blocking it would kill the
     swipe gesture), and a drag that merely ends over the peek tile is ignored so normal
     carousel swiping still works. */
  const scroller = this.shadowRoot ? this.shadowRoot.getElementById('media_row') : null;
  if (scroller && !scroller.__npPeekTap) {
    scroller.__npPeekTap = true;
    let sx = 0, sy = 0, stime = 0, clickBlockUntil = 0;
    const slotOf = (ev) => {
      const path = ev.composedPath ? ev.composedPath() : [];
      for (const n of path) {
        if (n === scroller) break;
        if (n && n.id && /^media[1-9]$/.test(n.id)) return n;
      }
      return null;
    };
    const edges = () => {
      const cs = getComputedStyle(scroller);
      const sr = scroller.getBoundingClientRect();
      return {
        left: sr.left + (parseFloat(cs.paddingLeft) || 0),
        right: sr.right - (parseFloat(cs.paddingRight) || 0),
      };
    };
    /* A snapped tile routinely lands a fraction of a pixel outside the content box, and
       the old 1px test read that as a peek - the tile then swallowed every tap forever. */
    const hiddenBy = (slot) => {
      const r = slot.getBoundingClientRect();
      if (r.width < 2) return 0;
      const e = edges();
      return Math.max(e.left - r.left, r.right - e.right, 0);
    };
    /* button-card's action handler is one <button-card-action-handler> on document.body.
       Swallowing touchend leaves its 500ms hold timer running, which then paints its
       hold circle over the page with nothing left to clear it. Its own document-level
       touchcancel listener is the reset. */
    const clearHold = () => {
      try { document.dispatchEvent(new Event('touchcancel')); } catch (e) {}
    };
    scroller.addEventListener('touchstart', (ev) => {
      const t = ev.touches && ev.touches[0];
      if (!t) return;
      sx = t.clientX; sy = t.clientY; stime = Date.now();
    }, { passive: true, capture: true });
    const intercept = (ev) => {
      const slot = slotOf(ev);
      if (!slot) return;
      if (ev.type === 'click' && Date.now() < clickBlockUntil) {
        ev.stopPropagation();
        if (ev.cancelable) ev.preventDefault();
        return;
      }
      if (hiddenBy(slot) <= 8) return;
      if (ev.type === 'touchend') {
        const t = ev.changedTouches && ev.changedTouches[0];
        if (t && (Math.abs(t.clientX - sx) > 10 || Math.abs(t.clientY - sy) > 10)) return;
        if (Date.now() - stime > 500) return;
      }
      /* Once the scroller is at its limit the tile cannot stop being clipped, so
         swallowing the tap there is a permanently dead button. Let it through. */
      const max = Math.max(0, scroller.scrollWidth - scroller.clientWidth);
      const want = scroller.scrollLeft + (slot.getBoundingClientRect().left - edges().left);
      const target = Math.max(0, Math.min(max, want));
      if (Math.abs(target - scroller.scrollLeft) < 4) return;
      ev.stopPropagation();
      if (ev.cancelable) ev.preventDefault();
      clickBlockUntil = Date.now() + 400;
      clearHold();
      scroller.scrollTo({ left: target, behavior: 'smooth' });
    };
    scroller.addEventListener('touchend', intercept, true);
    scroller.addEventListener('click', intercept, true);
  }

  /* Per-slot exit. The wrapper is the only element that survives a departure (the tile
     inside it is rebuilt on nearly every render — probe: tile e2>e5>e7>e9), so all
     motion lives here.
     Collapsing width to 0 is what shifts the survivors LEFT: it's a layout change, so
     no surviving tile is transformed and no backdrop-filter drops. The fade+scale run
     on the exiting wrapper only, which is allowed precisely because it reaches zero.
     transform stays `none` (never `scale(1)`) at rest — an identity transform would
     still make the wrapper a containing block and kill the tile's blur permanently.
     Everything is a plain CSS transition off values re-emitted each render: nothing
     fills, nothing needs cleaning up, so a 12s gap to the next render is harmless. */
  /* Width the exiting slot occupied BEFORE it started leaving: peek applies whenever
     more than one slot was filled (counting the leaver itself), which is not the same
     as usesPeek — that already reflects the post-departure live count. */
  const occupied = plan.filter(Boolean).length;
  const exitChildW = occupied > 1 ? peekW : fullW;

  /* When the slot leaving is NOT the rightmost one, there is nothing to the right of the
     survivors to make room for — they should already BE full width as they slide across,
     so the collapse is the only motion. Growing into it reads as a second, laggy step.
     When the rightmost slot leaves it's the opposite: slot 1 expanding IS the motion that
     pushes it off, so survivors keep their width transition. */
  let lastOcc = -1;
  plan.forEach((p, i) => { if (p) lastOcc = i; });
  const anyExit = Object.keys(exitSlots).length > 0;
  const snapSurvivors = anyExit && !exitSlots[lastOcc];

  let slotCSS = '';
  for (let i = 0; i < flipIds.length; i++) {
    const id = flipIds[i];
    if (exitSlots[i]) {
      /* The tile inside is pinned to 100% of the wrapper by staticCSS, so a bare
         collapse would reflow its text and squash its artwork on the way out. Hold the
         child at the peek width and let the wrapper clip it instead, so it fades in
         place rather than deforming. scroll-snap-align is dropped too — a zero-width
         snap target is a scroll trap. */
      slotCSS += `#${id}{width:0!important;min-width:0!important;max-width:0!important;` +
        `margin-right:0!important;opacity:0;transform:scale(0.96);` +
        `pointer-events:none;overflow:hidden;scroll-snap-align:none;}` +
        `#${id} > *{width:${exitChildW}!important;min-width:${exitChildW}!important;` +
        `max-width:${exitChildW}!important;}`;
    }
    /* Arrival, still closed. Zero width with the tile inside pinned at its final size,
       so opening REVEALS it left-to-right instead of squashing it into place — the exit
       run backwards. transition:none holds it flat here; the moment the plan clears
       `pending` (artwork decoded, or the cap elapsed) the base rule takes over and it
       animates open, pushing everything to its right along by layout. Nothing
       transforms, so no surviving tile loses its blur. */
    /* NOTE: no opacity here, deliberately. An ancestor with opacity < 1 forms a
       backdrop root, so the tile's backdrop-filter would have nothing to sample and the
       glass would render unblurred for the whole reveal, popping in at the end — the
       same trap as animating transform. Width 0 + overflow:hidden already clips the tile
       completely, so the fade was only ever cosmetic. The reveal is pure width. */
    else if (hvOne && i !== oneIdx) {
      slotCSS += `#${id}{width:0!important;min-width:0!important;max-width:0!important;` +
        `margin-right:0!important;overflow:hidden;` +
        `border-radius:var(--np-inner-radius, 26px);` +
        `scroll-snap-align:none;pointer-events:none;}` +
        `#${id} > *{width:${fullW}!important;min-width:${fullW}!important;` +
        `max-width:${fullW}!important;}`;
    }
    else if (entering[i]) {
      slotCSS += `#${id}{width:0!important;min-width:0!important;max-width:0!important;` +
        `margin-right:0!important;overflow:hidden;` +
        `border-radius:var(--np-inner-radius, 26px);` +
        `scroll-snap-align:none;pointer-events:none;transition:none!important;}` +
        `#${id} > *{width:${activeW}!important;min-width:${activeW}!important;` +
        `max-width:${activeW}!important;}`;
    }
    /* Media filter open: every slot but the head collapses to zero width. Opening snaps
       (see the inColumn transition:none below); closing reopens these like an arrival.
       Pure width, never opacity or transform — these tiles are visible again at the end,
       and either would strip their backdrop-filter on the way back in. */
    else if (useColumn && i !== headIdx) {
      /* border-radius on the clip: without it the wrapper's square edge cuts straight
         through the tile's rounded corner and you see a hard vertical slice. Matching
         the tile's own radius makes the clip edge stay rounded as it closes. */
      slotCSS += `#${id}{width:0!important;min-width:0!important;max-width:0!important;` +
        `margin-right:0!important;overflow:hidden;` +
        `border-radius:var(--np-inner-radius, 26px);` +
        `scroll-snap-align:none;pointer-events:none;}` +
        `#${id} > *{width:${peekW}!important;min-width:${peekW}!important;` +
        `max-width:${peekW}!important;}`;
    }
    else if (snapSurvivors) {
      slotCSS += `#${id}{transition-property:opacity,transform!important;}`;
    }
    /* Media filter OPEN: same motion, its own much shorter duration. The filter view
       itself appears instantly, so the row has to arrive on the same beat — at the .46s
       used elsewhere the tile visibly trails the mode switch, and at 0s it reads as a
       jump cut. The curve is unchanged and heavily front-loaded, so this stays smooth
       rather than clipped.
       This also gives the CLOSE animation for free with no direction tracking: leaving
       column mode swaps this rule for the base transition in the SAME style change as
       the widths, and CSS starts transitions from the after-change style — so closing
       runs at the full .46s while opening runs at --np-column-dur. */
    if (useColumn || closingColumn) {
      const isHead = (i === headIdx);
      const d = isHead ? columnDur : columnCollapseDur;
      const e = isHead ? columnSpring : columnEase;
      slotCSS += `#${id}{transition:` +
        `width ${d} ${e},` +
        `min-width ${d} ${e},` +
        `max-width ${d} ${e},` +
        `margin-right ${d} ${e}!important;}`;
    }

    /* Slot taken over by a different source: snap to the new geometry instead of
       animating out of whatever the previous occupant left behind. */
    if (slotSnapped[id]) slotCSS += `#${id}{transition:none!important;}`;

    /* Was computed and thrown away. Honor it: every motion in this row is a width
       transition, so suppressing them here removes all of it at once. */
    if (reduceMotion || hvOne) slotCSS += `#${id}{transition:none!important;}`;
  }

  return staticCSS + `
    /* Kept for debugging only - the slot rules above use the literal, NOT this var.
       Measured: when the stylesheet is regenerated, the !important declarations take
       effect immediately while this non-important custom property still resolves to the
       previous render's value, so a slot reading var(--np-active-w) applies a stale
       width. Combined with a snap render that locked the stale peek value in, that is
       what left the survivor narrow. */
    :host { --np-active-w: ${activeW}; --np-active-gap: ${activeGap}; --np-bloom-strength: 0.62;
            --np-slot-cap: 100vw; }
    #media1, #media2, #media3, #media4, #media5,
    #media6, #media7, #media8, #media9 {
      width: ${activeW} !important;
      min-width: ${activeW} !important;
      max-width: ${activeW} !important;
      margin-right: ${activeGap} !important;
      opacity: 1;
      transform: none;
      transition:
        width .46s cubic-bezier(0.32, 0.72, 0, 1),
        min-width .46s cubic-bezier(0.32, 0.72, 0, 1),
        max-width .46s cubic-bezier(0.32, 0.72, 0, 1),
        margin-right .46s cubic-bezier(0.32, 0.72, 0, 1),
        opacity .24s ease,
        transform .30s cubic-bezier(0.32, 0.72, 0, 1);
      flex: 0 0 auto !important;
      scroll-snap-align: start;
      scroll-snap-stop: always;
      box-sizing: border-box !important;
      overflow: visible;
      display: flex;
      flex-direction: column;
    }
    ${lsQ} {
      ${lsSlots} {
        width: ${lsColW} !important;
        min-width: ${lsColW} !important;
        max-width: ${lsColW} !important;
      }
      ${!useColumn && lastOcc >= 0
        ? `#${flipIds[lastOcc]} { margin-right: 0 !important; }` : ''}
    }
  ` + slotCSS;
]]]

