  const tap = wid ? ` role="button" ontouchend="event.preventDefault();${go}" onclick="${go}"` : '';
  const wx = x ? `<span class="hvw"${tap} style="display:inline-flex;align-items:center;gap:7px;height:40px;cursor:pointer;-webkit-tap-highlight-color:transparent">${ic}<b style="font-weight:600;color:var(--hv-ink, #fff)">${x.t}°</b></span>` : '';
