name.font-size:
[[[
  if (!document.documentElement.classList.contains("hemma-hv")) return "var(--hero-room-name-size-current, clamp(38px, 4vw + 2px, 64px))";
  const f = states['input_select.hemma_mobile_filter']?.state ?? 'all';
  const t = f === 'all' && window.hemmaGreeting ? String(window.hemmaGreeting(hass, states, variables)).replace(/&amp;/g, '&').replace(/&lt;/g, '<') : '';
  if (!t) return "34px";
  // Longer names step down to fit one line rather than wrapping under the weather.
  const c = (window._hemmaGreetCtx = window._hemmaGreetCtx || document.createElement('canvas').getContext('2d'));
  c.font = '700 34px ' + (getComputedStyle(document.body).fontFamily || '-apple-system, system-ui');
  const w = c.measureText(t).width * 1.02, room = Math.max(200, window.innerWidth - 32);
  return Math.max(24, Math.min(34, Math.floor(34 * room / w))) + "px";
]]]

