custom_fields.scenes_row:
[[[
  const SC = window._hemmaSC;
  if (!SC) return '';

  const _self = this;
  const ids = SC.list(states, typeof hass !== 'undefined' ? hass : null, variables);
  if (!ids.length) return '';

  // Surface key survives a card rebuild; smart-row recreates its children.
  const _key = (variables.layout || 'row') + '|' + (variables.room || '') + '|' + ids.join(',');

  if (SC.frozenHtml) {
    const _frozen = SC.frozenHtml(_key);
    if (_frozen) return _frozen;
  }
  SC.prefetch(ids, states);

  const grid = variables.layout === 'grid';
  const icons = variables.scene_icons || {};
  // Colors live on SC so the JS-built Scenes page and room rows see them too.
  if (SC.noteColors) SC.noteColors(variables.scene_colors);
  const opts = {
    transition: variables.scene_transition == null ? 4 : variables.scene_transition,
    width: variables.chip_width || 'min(41vw, 176px)',
    grid: grid,
  };

  const _sid = SC.surfaceId ? SC.surfaceId(_key) : null;
  const ord = SC.order ? SC.order(ids, states, _sid) : null;

  if (SC.flip) {
    if (!_self._scBusyBound) {
      _self._scBusyBound = true;
      try {
        _self.addEventListener('scroll', () => { window._hemmaSCBusy = Date.now(); }, { passive: true });
      } catch (_) {}
    }
    requestAnimationFrame(() => { try { SC.flip(_self, _key); } catch (_) {} });
  }

  const inner = grid
    ? 'display:grid;grid-template-columns:var(--hemma-scene-grid-cols, repeat(2,minmax(0,1fr)));gap:var(--hemma-scene-grid-row-gap, 12px) var(--hemma-scene-grid-col-gap, 11px);width:100%;pointer-events:auto;'
    : 'display:flex;flex-direction:row;gap:8px;width:max-content;min-width:100%;pointer-events:auto;';

  const dbg = (variables.sort_debug === true && SC.sortDebug)
    ? '<div style="font:11px/1.4 ui-monospace,monospace;color:rgba(255,255,255,0.75);'
      + 'padding:2px 0 6px 0;white-space:pre-wrap;word-break:break-all;">'
      + SC.sortDebug() + '</div>'
    : '';

  const _html = dbg + '<div style="' + inner + '">'
    + ids.map((id) => SC.chipHtml(id, states, Object.assign(
        { icon: icons[id] || null, order: ord ? ord.get(id) : null, sid: _sid }, opts))).join('')
    + '</div>';
  if (SC.noteHtml) SC.noteHtml(_key, _html);
  return _html;
]]]

hemma_np_init.value:
[[[
  // Start minimized. The collapse lives in a persistent helper shared by
  // every room and every device, so "start" can only mean this page
  // load: reassert it once, then leave the caret to own it for the rest
  // of the session. Skipped when the helper is absent, so a config
  // without the Hemma package never calls a service on nothing.
  if (variables.start_minimized && !window._hemmaNPStartMin) {
    window._hemmaNPStartMin = 1;
    const _mz = states[variables.minimized_entity];
    if (_mz && _mz.state === 'off') {
      hass.callService('input_boolean', 'turn_on', { entity_id: variables.minimized_entity });
    }
  }
  // hemma-core.js owns the collector - one definition, served by the
  // integration. If it has not loaded, say so once and let the panel
  // draw empty rather than throwing on every template below.
  if (typeof window._hemmaNP !== 'function' && !window._hemmaNPNoCore) {
    window._hemmaNPNoCore = 1;
    // Not immediately: a module resource is still loading while the
    // first render evaluates this, so the bare check cried wolf on
    // every cold load and then latched, leaving a stale error in the
    // console for a file that had in fact arrived.
    setTimeout(function () {
      if (typeof window._hemmaNP === 'function') return;
      console.error('Hemma: hemma-core.js has not loaded, so Now Playing '
        + 'cannot collect sources. Check the dashboard resource for it.');
    }, 5000);
  }
  return true;
]]]

settled.value:
[[[
  // NOT Object.assign({}, variables, {...}) - variables includes `settled` itself, so spreading
  // it triggers button-card's "Detected a loop" error; read specific keys instead.
  const V = { pause_timeout_minutes: variables.pause_timeout_minutes };
  for (let i = 1; i <= 10; i++) {
    V['show_media_player_' + i] = variables['show_media_player_' + i];
    V['media_player_' + i] = variables['media_player_' + i];
  }
  for (let i = 1; i <= 2; i++) {
    V['show_plex_' + i] = variables['show_plex_' + i];
    V['plex_stream_' + i] = variables['plex_stream_' + i];
    V['show_psn_' + i] = variables['show_psn_' + i];
    V['psn_' + i] = variables['psn_' + i];
  }
  V.show_discord = variables.show_discord;
  V.discord_user = variables.discord_user;
  V.discord_image = variables.discord_image;
  V.discord_game = variables.discord_game;
  V.discord_online = variables.discord_online;
  V.discord_details = variables.discord_details;
  V.discord_label = variables.discord_label;
  V.show_steam = variables.show_steam;
  V.plex_hide_users = variables.plex_hide_users;
  V.steam_account = variables.steam_account;
  V.steam_online = variables.steam_online;
  V.steam_game = variables.steam_game;
  V.steam_image = variables.steam_image;
  V.steam_label = variables.steam_label;
  V.duplicate_game = variables.duplicate_game;
  V.pinned_key = states[variables.pin_entity]?.state || '';

  // Both live in hemma-core.js. Without it there is nothing to collect,
  // so draw empty rather than throwing on every consumer below.
  if (typeof window._hemmaNPDesktopSettle !== 'function') {
    return typeof window._hemmaNPView === 'function'
      ? window._hemmaNPView(states, V) : [];
  }
  const result = window._hemmaNPDesktopSettle(states, V);
  if (result.pending) {
    // Mid-grace/departure-hold - nudge a re-render once it finishes, since nothing else would trigger it.
    try { clearTimeout(window._hemmaNPDesktopRecheckTimer); } catch (e) {}
    window._hemmaNPDesktopRecheckTimer = setTimeout(() => {
      try {
        if (this.hass) this.hass = Object.assign({}, this.hass);
        else if (typeof this.requestUpdate === 'function') this.requestUpdate();
      } catch (e) {}
    }, 650);
  }
  return result.list;
]]]

card.--np-open:
[[[
  const v = variables?.enabled;
  const on = (v === undefined || v === null) ? true :
    (typeof v === 'boolean') ? v :
    !['false','0','no','off','disabled'].includes(String(v).trim().toLowerCase());
  const open = (on && typeof window._hemmaNP === 'function'
    && window._hemmaNP(states, Object.assign({}, variables, { pinned_key: states[variables.pin_entity]?.state || '' })).length) ? 1 : 0;

  if ((this._npPanelOpen ?? 0) !== open) {
    const runDroplet = () => {
      const card = this.shadowRoot?.querySelector('ha-card');
      if (!card) return;
      try { this._npPanelAnim?.cancel(); } catch (e) {}

      this._npPanelAnim = card.animate(
        open
          ? [{ opacity: 0 }, { opacity: 1 }]
          : [{ opacity: 1 }, { opacity: 0 }],
        {
          duration: open ? 340 : 260,
          easing: open ? 'ease-out' : 'ease-in',
          fill: 'both',
        }
      );

      this._npPanelAnim.finished
        .then(() => { try { this._npPanelAnim?.cancel(); } catch (e) {} })
        .catch(() => {});
    };

    if (this.shadowRoot?.querySelector('ha-card')) runDroplet();
    else requestAnimationFrame(runDroplet);
  }
  this._npPanelOpen = open;


  try {
    this.style.setProperty('--np-open', String(open));
    this.style.setProperty('--np-ptr', open ? 'auto' : 'none');
    this.style.setProperty('--np-vis', open ? 'inherit' : 'hidden');
  } catch (e) {}
  return open;
]]]

card.--np-min-hold:
[[[
  const n = Math.max(1, (variables.settled || []).length);
  // MUST match NP_OUT_STAGGER and NP_OUT_DUR in --np-min.
  return 'calc(var(--np-min, 0) * ' + ((n - 1) * 20 + 180) + 'ms)';
]]]

card.--np-min:
[[[
  if (!this._npKickWired) {
    this._npKickWired = true;
    const el = this;
    window._hemmaNPKick = [() => window.hemmaKick?.(el)];
  }

  const _mzs = states[variables.minimized_entity];
  const _real = _mzs?.state === 'on' ? 1 : 0;
  const minimized = window.hemmaOptimistic
    ? window.hemmaOptimistic('np-min', _mzs, _real) : _real;

  // First evaluation only records state - no morph on cold load; the shell's own droplet already owns first appearance.
  if (this._npMinState === undefined) {
    this._npMinState = minimized;
    return minimized;
  }
  if (this._npMinState === minimized) return minimized;
  this._npMinState = minimized;

  const opening = minimized === 0;
  const reduce = window.matchMedia
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduce) return minimized;

  const root = this.shadowRoot;
  if (!root) return minimized;

  const targets = [];
  const push = (holder) => {
    const bc = holder ? holder.querySelector('button-card') : null;
    const sr = bc && bc.shadowRoot;
    const card = sr ? sr.querySelector('ha-card') : null;
    if (!card) return;
    // A collapsed slot is height:0 - skip it or it steals a stagger slot from a visible tile.
    if (card.getBoundingClientRect().height < 4) return;
    targets.push({ host: bc, card: card, container: sr.getElementById('container') });
  };

  const stackHost = root.querySelector('#np_main button-card');
  const stackRoot = stackHost && stackHost.shadowRoot;
  if (stackRoot) {
    for (let i = 1; i <= 7; i++) push(stackRoot.querySelector('#s' + i));
  }
  if (!targets.length) return minimized;

  const n = targets.length;

  const headEl = root.querySelector('#np_head');
  const headInset = headEl
    ? (parseFloat(getComputedStyle(headEl).paddingRight) || 0) : 0;

  const spring = (t, zeta, omega) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    const wd = omega * Math.sqrt(Math.max(1e-6, 1 - zeta * zeta));
    return 1 - Math.exp(-zeta * omega * t) *
      (Math.cos(wd * t) + ((zeta * omega) / wd) * Math.sin(wd * t));
  };
  const easeIn = (t) => t * t;

  // Flip to false to put the original droplet back and compare.
  const REFINED = true;
  const M = REFINED ? {
    droplet: false, scale0: 0.92, outScale: 0.96, zeta: 0.86,
    inDur: 300, inStagger: 28, outDur: 180, outStagger: 20,
  } : {
    droplet: true, zeta: 0.74,
    inDur: 360, inStagger: 40, outDur: 210, outStagger: 26,
  };

  const DROP = 40;
  const SAMPLES = 26;
  const NP_OUT_DUR = M.outDur;
  const NP_OUT_STAGGER = M.outStagger;

  targets.forEach((t, i) => {
    const card = t.card;
    const r = card.getBoundingClientRect();
    const w = Math.max(r.width, 1);
    const h = Math.max(r.height, 1);
    if (w < 8 || h < 8) return;

    const sx0 = Math.min(0.9, DROP / w);
    const sy0 = Math.min(0.9, DROP / h);

    const R = parseFloat(getComputedStyle(card).borderTopLeftRadius) || 26;
    const rx0 = (DROP / 2) / sx0;
    const ry0 = (DROP / 2) / sy0;

    // Offset from the droplet's origin up onto the waveform toggle, so it is born at the button.
    const dx = 10;
    const dy = -20;
    const originX = Math.max(0, w - headInset);

    const extra = n > 1 ? (i / (n - 1)) : 0;
    const zeta = M.zeta - ((M.droplet ? 0.09 : 0.03) * extra);

    const kf = [];
    for (let k = 0; k <= SAMPLES; k++) {
      const u = k / SAMPLES;
      if (!M.droplet) {
        let sc, op;
        if (opening) {
          const p = spring(u, zeta, 9);
          sc = M.scale0 + (1 - M.scale0) * p;
          op = Math.min(1, u / 0.32);
        } else {
          const e = easeIn(u);
          sc = 1 - (1 - M.outScale) * e;
          op = Math.max(0, 1 - u);
        }
        kf.push({
          offset: u,
          easing: 'linear',
          transformOrigin: opening
            ? (originX.toFixed(1) + 'px 0%') : '50% 50%',
          translate: '0px 0px',
          scale: sc.toFixed(4),
          opacity: op.toFixed(3),
        });
        continue;
      }

      let px, py, op;
      if (opening) {
        px = spring(u, zeta, 9);
        py = spring(Math.max(0, (u - 0.10) / 0.90), zeta + 0.04, 9);
        op = Math.min(1, u / 0.26);
      } else {
        const e = (2.10 * u * u * u) - (1.10 * u * u);
        px = 1 - e;
        py = 1 - e;
        op = Math.max(0, 1 - Math.pow(u, 1.6));
      }
      const sx = sx0 + (1 - sx0) * px;
      const sy = sy0 + (1 - sy0) * py;
      kf.push({
        offset: u,
        easing: 'linear',
        transformOrigin: originX.toFixed(1) + 'px 0%',
        translate: (dx * (1 - px)).toFixed(2) + 'px ' +
                   (dy * (1 - px)).toFixed(2) + 'px',
        scale: sx.toFixed(4) + ' ' + sy.toFixed(4),
        borderRadius: (rx0 + (R - rx0) * px).toFixed(1) + 'px / ' +
                      (ry0 + (R - ry0) * py).toFixed(1) + 'px',
        opacity: op.toFixed(3),
      });
    }

    const order = opening ? i : (n - 1 - i);
    const delay = order * (opening ? M.inStagger : NP_OUT_STAGGER);
    const dur = opening ? (M.inDur + extra * (M.droplet ? 50 : 20))
                        : NP_OUT_DUR;

    const run = (el, pseudo) => {
      if (!el) return;
      const opts = { duration: dur, delay: delay, fill: 'both' };
      if (pseudo) opts.pseudoElement = pseudo;
      // The glass pseudo rests below full opacity; animating it to 1 drew its drop shadow heavier than at rest.
      const base = pseudo ? (parseFloat(getComputedStyle(el, pseudo).opacity) || 0) : 1;
      const frames = base < 1 ? kf.map((f) => Object.assign({}, f, { opacity: (parseFloat(f.opacity) * base).toFixed(3) })) : kf;
      let anim;
      try { anim = el.animate(frames, opts); } catch (e) { return; }
      anim.finished
        .then(() => { try { anim.cancel(); } catch (e) {} })
        .catch(() => {});
    };

    run(card, null);
    run(t.host, '::after');
  });

  return minimized;
]]]

