custom_fields.ring:
[[[
  if (!variables.ring || !variables.src?.controls?.toggle) return '';
  const s = variables.src;
  const SW = 2.2;
  const R = 20 - (SW / 2) - 0.5;
  const C = 2 * Math.PI * R;

  const st = String(s.state || '').toLowerCase();
  const trackable = st === 'playing' || st === 'buffering' || st === 'paused';

  let arc = '';
  if (trackable && Number.isFinite(s.dur) && s.dur > 0 && Number.isFinite(s.pos)) {
    const elapsed = s.playing && s.posAt ? (Date.now() - s.posAt) / 1000 : 0;
    const now = Math.min(s.dur, Math.max(0, s.pos + elapsed));
    const frac = Math.max(0, Math.min(1, now / s.dur));
    const remain = Math.max(0, s.dur - now);
    const anim = s.playing && remain > 0
      ? `animation: np-ring-advance ${remain.toFixed(1)}s linear forwards;`
      : '';
    // Paused at the very top of an item hasn't got progress to show yet.
    if (s.playing || now > 1) {
      arc = `
        <circle class="np-ring-track" cx="20" cy="20" r="${R.toFixed(3)}"></circle>
        <circle class="np-ring-fill" cx="20" cy="20" r="${R.toFixed(3)}"
          transform="rotate(-90 20 20)"
          style="stroke-dasharray: ${C.toFixed(3)}; stroke-dashoffset: ${(C * (1 - frac)).toFixed(3)}; ${anim}"></circle>
      `;
    }
  }

  return `
    <svg class="np-ring" viewBox="0 0 40 40" aria-hidden="true">
      <circle class="np-ring-disc" cx="20" cy="20" r="${(R - (SW / 2)).toFixed(3)}"></circle>
      ${arc}
    </svg>
  `;
]]]

