#caret{
  overflow: visible !important;
}

#caret.ellipsis{
  overflow: visible !important;
  text-overflow: clip !important;
}

.np-head-wave{
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--np-wave-u, 8px) * 0.34);
  flex: none;
  /* MUST match hemma_menu_icon's settings button exactly - same size, same
      fill, no rim and no backdrop-filter. Flat, the way the reference draws
      them; the glass rim read as a raised bubble at this diameter and the
      two buttons stopped looking like one control set. */
  width: var(--hemma-chrome-btn-size, 34px);
  height: var(--hemma-chrome-btn-size, 34px);
  box-sizing: border-box;
  border-radius: 50%;
  /* Inverts when the panel it controls is open, the same rule the settings
     button follows: fill says active, geometry never changes.
     --np-head-min is 1 while collapsed, 0 while expanded. */
  background: color-mix(in srgb, #fff calc((1 - var(--np-head-min, 0)) * var(--hemma-np-invert, 1) * 100%),
                        var(--hemma-chrome-fill, rgba(0,0,0,0.40)));
  /* No backdrop-filter, deliberately. A translucent fill plus a blur renders
     differently depending on the backdrop root its ancestors create, and
     this sits inside #now_playing while the settings button sits straight
     over the photo - two identical declarations, two different results. A
     flat fill cannot disagree. MUST match hemma_settings_button. */
  /* Bars sized from their own unit so they clear the rim as they animate. */
  --np-wave-u: calc(var(--hemma-u, 10px) * 0.66);
  opacity: var(--np-head-open, 0);
  transform: scale(calc(0.4 + (0.6 * var(--np-head-open, 0))));
  transform-origin: center;
  transition:
    opacity 0.32s cubic-bezier(0.32, 0.72, 0, 1),
    background-color 0.34s cubic-bezier(0.32, 0.72, 0, 1),
    transform 0.46s cubic-bezier(0.34, 1.42, 0.5, 1);
  transition-delay: calc((1 - var(--np-head-open, 0)) * 0.42s);
}

.np-wave-bar{
  /* One width in both states. It used to vary with --np-head-min - first
     thinner when inverted, then thicker once I compensated - so it was never
     the same bar twice. This is the inverted width, kept for both. */
  width: calc(var(--np-wave-u, 8px) * 0.25 + 0.7px);
  height: calc(var(--np-wave-u, 8px) * 1.2);
  border-radius: 1px;
  transform-origin: center;
  background: color-mix(in srgb, #1c1c20 calc((1 - var(--np-head-min, 0)) * var(--hemma-np-invert, 1) * 100%),
                        var(--hemma-settings-ink, rgba(255,255,255,0.90)));
  transition: width 0.34s cubic-bezier(0.32, 0.72, 0, 1), background-color 0.34s cubic-bezier(0.32, 0.72, 0, 1);
  animation: np-wave-bounce 1.53s ease-in-out infinite;
  /* Stopped, not paused. animation-play-state froze each bar wherever its
     own cycle had reached - every bar has a different duration and delay -
     so a stopped waveform sometimes held all five near scaleY(0.42) and the
     short ones shrank to a few px, reading as the settings button's dots.
     With no animation the bars sit at the staggered heights below, which is
     unmistakably an equaliser. */
  animation-name: var(--np-head-anim, none);
}

.np-wave-bar:nth-child(1){ height: calc(var(--np-wave-u, 8px) * 0.8); animation-duration: 1.19s;  animation-delay: 0.05s; }
.np-wave-bar:nth-child(2){ height: calc(var(--np-wave-u, 8px) * 1.3); animation-duration: 1.615s; animation-delay: 0.15s; }
.np-wave-bar:nth-child(3){ height: calc(var(--np-wave-u, 8px) * 1.7); animation-duration: 1.02s;  animation-delay: 0s;    }
.np-wave-bar:nth-child(4){ height: calc(var(--np-wave-u, 8px) * 1.2); animation-duration: 1.785s; animation-delay: 0.2s;  }
.np-wave-bar:nth-child(5){ height: calc(var(--np-wave-u, 8px) * 0.8); animation-duration: 1.36s;  animation-delay: 0.1s;  }

/* Rests at full height at both ends so it leaves and rejoins the stopped
   pose without a jump, and a frozen frame can never be the short one. */
@keyframes np-wave-bounce{
  0%, 100% { transform: scaleY(1); }
  50%      { transform: scaleY(0.42); }
}

@media (prefers-reduced-motion: reduce) {
  .np-head-wave, .np-wave-bar{ transition: none; animation: none !important; }
  .np-head-wave{ transform: none; }
}

hold_src.value:
[[[
  const horizontal = variables.entry_direction === 'horizontal';

  if (!horizontal) return variables.src;

  window._hemmaNPSlotState = window._hemmaNPSlotState || {};
  const store = variables.slot_id
    ? (window._hemmaNPSlotState[variables.slot_id] = window._hemmaNPSlotState[variables.slot_id] || {})
    : this;

  const el = this;
  const scheduleRecheck = (ms) => {
    try { clearTimeout(store._npRecheckTimer); } catch (e) {}
    store._npRecheckTimer = setTimeout(() => {
      try {
        // Forcing a render with no state change takes BOTH steps, and neither alone works:
        //  1. button-card defines `set hass` with no getter, so the old `if (el.hass)`
        //     guard always read undefined and fell through to a bare requestUpdate().
        //  2. button-card's shouldUpdate() only passes on a _config change, a timer tick,
        //     or _hasAnEntityChanged - so a hass clone carrying identical states is
        //     rejected, and a bare requestUpdate() never reaches render().
        // _config is a reactive @state(), so marking it dirty is what actually gets the
        // templates re-evaluated. This is the path a paused tile depends on to lapse: it
        // emits no state change of its own, so nothing else will re-run the collector.
        const h = el._hass || el.hass;
        if (h) el.hass = Object.assign({}, h);
        if (typeof el.requestUpdate === 'function') el.requestUpdate('_config', undefined);
      } catch (e) {}
      try { window._hemmaNPMobileRecheck?.(states); } catch (e) {}
    }, ms + 30);
  };

  const live = variables.src;
  const finish = (result) => {
    try { window._hemmaNPSyncMobileRow?.(el, states); } catch (e) {}
    if (result && result.state === 'paused') {
      const until = Number(result.pauseUntil) || 0;
      const left = until ? (until - Date.now()) : 0;
      scheduleRecheck(until ? Math.min(30000, Math.max(1000, left + 150)) : 20000);
    }
    return result;
  };

  if (live) {
    store._npHoldSrc = live;
    store._npHoldAt = 0;
    return finish(live);
  }

  if (!store._npHoldSrc) return finish(null);
  if (!store._npHoldAt) store._npHoldAt = Date.now();
  const heldFor = Date.now() - store._npHoldAt;
  if (heldFor < 500) {
    scheduleRecheck(500 - heldFor);
    return finish(store._npHoldSrc);
  }
  store._npHoldSrc = null;
  return finish(null);
]]]

card.--np-marquee-scan:
[[[
  const el = this;
  const scan = () => {
    const root = el.shadowRoot;
    if (!root) return;
    const lines = root.querySelectorAll('.np-line');
    if (!lines.length) return;
    // Seamless one-direction loop: a second copy offset by GAP_PX; animating to -(singleWidth+GAP) lands it exactly where the original started.
    const SPEED_PX_S = 26;
    const GAP_PX = 48;
    const MIN_DUR_S = 4;
    // Plain CSS keyframe shape (not WAAPI offsets) so pause time scales with title length.
    const PAUSE_FRACTION = 0.12;
    lines.forEach((ln) => {
      // Measures the original (first child) alone - scrollWidth would double-count if a clone from a previous pass already exists.
      const original = ln.firstElementChild;
      if (!original) return;
      const singleWidth = original.getBoundingClientRect().width;
      const over = singleWidth - ln.clientWidth;
      const clone = ln.children[1] || null;

      if (over > 4) {
        const loopDist = singleWidth + GAP_PX;
        const dur = Math.max(MIN_DUR_S, (loopDist / SPEED_PX_S) / (1 - PAUSE_FRACTION));
        const mqv = loopDist.toFixed(0) + 'px', durv = dur.toFixed(2) + 's';
        const key = original.className.split(' ')[0] + '|' + original.textContent;
        const mq = el._npMq = el._npMq || {};
        const kept = mq[key] && mq[key].mq === mqv && mq[key].dur === durv && ln.classList.contains('np-scroll');
        if (!kept) {
          const base = ln.querySelector('.np-sub') ? 1.2 : 0;
          Object.keys(mq).forEach((k) => { if (k.split('|')[0] === key.split('|')[0]) delete mq[k]; });
          mq[key] = { mq: mqv, dur: durv, base, gap: GAP_PX, t0: Date.now() };
          ln.style.setProperty('--np-mq', mqv);
          ln.style.setProperty('--np-marquee-dur', durv);
          // Set per line: edge-fade (on the line) and translateX (on the text) must share duration+delay to stay in lockstep.
          ln.style.setProperty('--np-mq-delay', base + 's');
        }
        ln.classList.add('np-scroll');
        if (!clone) {
          const dupe = original.cloneNode(true);
          dupe.classList.add('np-marquee-clone');
          dupe.setAttribute('aria-hidden', 'true');
          dupe.style.marginLeft = GAP_PX + 'px';
          ln.appendChild(dupe);
        }
      } else {
        if (el._npMq) delete el._npMq[original.className.split(' ')[0] + '|' + original.textContent];
        ln.style.removeProperty('--np-mq');
        ln.style.removeProperty('--np-marquee-dur');
        ln.style.removeProperty('--np-mq-delay');
        ln.classList.remove('np-scroll');
        if (clone) clone.remove();
      }
    });
    if (!el._npMqObs && window.ResizeObserver) {
      const target = root.getElementById('container');
      if (target) {
        el._npMqObs = new ResizeObserver(() => requestAnimationFrame(scan));
        try { el._npMqObs.observe(target); } catch (e) {}
      }
    }
  };
  // Bounded wait: field may not be in the shadow DOM yet the frame after render (same pattern as the artwork layers).
  let tries = 0;
  const wait = () => {
    if (el.shadowRoot?.querySelector('.np-line')) { scan(); return; }
    if (++tries < 30) requestAnimationFrame(wait);
  };
  requestAnimationFrame(wait);
  return 1;
]]]

card.--np-art:
[[[
  const s = variables.hold_src;
  const hold = window._hemmaNPArtHold = window._hemmaNPArtHold || {};
  const warm = window._hemmaNPArtWarm = window._hemmaNPArtWarm || new Map();
  const k = s ? ((s.entity || '') + '|' + (s.key || s.kind || '')) : '';
  const cur = s?.art || null;
  const id = s ? ((s.title || '') + '|' + (s.subtitle || '')) : '';
  const el = this;

  const artk = (u) => {
    const t = String(u || '');
    const q = t.indexOf('?');
    if (q < 0) return t + '|' + id;
    const rest = t.slice(q + 1).split('&')
      .filter((p) => p.slice(0, 6) !== 'token=' && p.slice(0, 8) !== 'authSig=')
      .sort().join('&');
    return t.slice(0, q) + (rest ? '?' + rest : '') + '|' + id;
  };

  const touch = (p) => {
    const rec = warm.get(p);
    if (rec) { warm.delete(p); warm.set(p, rec); }
    return rec;
  };
  // LRU rather than insertion order, so the cover on screen is never the one evicted.
  const trim = () => {
    while (warm.size > 24) {
      const p = warm.keys().next().value;
      const rec = warm.get(p);
      warm.delete(p);
      if (rec && rec.obj) { try { URL.revokeObjectURL(rec.obj); } catch (e) {} }
    }
  };
  const rotates = (u) => {
    try {
      const p = new URL(u, location.origin);
      return p.origin === location.origin &&
        (p.searchParams.has('token') || p.searchParams.has('authSig'));
    } catch (e) { return false; }
  };

  const claim = (u) => {
    const p = artk(u);
    let rec = touch(p);
    if (!rec) { rec = {}; warm.set(p, rec); trim(); }
    if (rec.obj || rec.busy || rec.tried === u) return rec;
    rec.tried = u;
    if (!rotates(u)) {
      try {
        const im = new Image();
        im.decoding = 'async';
        im.src = u;
        rec.img = im;
        im.decode?.().catch(() => {});
      } catch (e) {}
      return rec;
    }
    rec.busy = true;
    fetch(u, { credentials: 'same-origin' })
      .then((r) => (r.ok ? r.blob() : Promise.reject(r.status)))
      .then((b) => {
        const obj = URL.createObjectURL(b);
        const publish = () => {
          rec.busy = false;
          rec.obj = obj;
          const card = el.shadowRoot?.querySelector('ha-card');
          if (card) card.style.setProperty('--np-art', 'url("' + obj + '")');
        };
        // Decoded first, or the swap off the token url is a repaint with nothing to show.
        try {
          const im = new Image();
          im.decoding = 'async';
          im.src = obj;
          rec.img = im;
          if (im.decode) im.decode().then(publish, publish); else publish();
        } catch (e) { publish(); }
      })
      .catch(() => { rec.busy = false; });
    return rec;
  };

  let u = null;
  if (cur) {
    const rec = claim(cur);
    // Until the blob lands, paint the CURRENT url - it is the only one HA will serve.
    u = (rec && rec.obj) || cur;
    if (k) hold[k] = { id: id, url: u };
  } else if (k) {
    const prev = hold[k];
    // Transient null between polls - hold the last good art, but only for this track.
    u = (prev && prev.id === id) ? prev.url : null;
  }
  if (window.hemmaArtXfade) window.hemmaArtXfade(el, u, id);

  return u ? `url("${u}")` : 'none';
]]]

card.--np-has-art:
[[[
  const s = variables.hold_src;
  const hold = window._hemmaNPArtHold || {};
  const k = s ? ((s.entity || '') + '|' + (s.key || s.kind || '')) : '';
  const id = s ? ((s.title || '') + '|' + (s.subtitle || '')) : '';
  const rec = k ? hold[k] : null;
  return ((rec && rec.id === id && rec.url) || s?.art) ? 1 : 0;
]]]

card.--np-swap:
[[[
  // hold_src (not src) avoids reading a one-poll-cycle blip as an exit+arrival bounce; store keyed by slot_id survives element rebuild (see slot_id note above).
  window._hemmaNPSlotState = window._hemmaNPSlotState || {};
  const store = variables.slot_id
    ? (window._hemmaNPSlotState[variables.slot_id] = window._hemmaNPSlotState[variables.slot_id] || {})
    : this;

  const key  = variables.hold_src?.key || '';
  const prev = store._npKey;
  const horizontal = variables.entry_direction === 'horizontal';

  // Container-owned motion: record the key so state stays coherent, but never animate.
  if (variables.swap_motion === false) {
    store._npKey = key;
    return key ? 1 : 0;
  }

  if (prev !== key) {
    const isExit  = !key;
    const isFirst = !prev && !isExit;
    // Boot timestamp distinguishes "already playing before page load" from "genuinely new arrival": store._npKey resets every page load, so !prev alone can't tell them apart. Only gates isFirst - exits/promotions/reassignments are untouched.
    window._hemmaNPBootAt = window._hemmaNPBootAt || Date.now();
    const booting = (Date.now() - window._hemmaNPBootAt) < 2500;
    const skipFirst = isFirst && (!horizontal || booting);

    if (!skipFirst && !isExit) {
      const c0 = this;
      if (c0) {
        if (horizontal) {
          c0.style.transformOrigin = '50% 50%';
          c0.style.transform = 'translateX(40px)';
        } else {
          c0.style.transformOrigin = '100% 0%';
          c0.style.transform = 'scale(0.16)';
        }
        c0.style.opacity = '0';
      }
    }

    requestAnimationFrame(() => {
      const card = this;
      // isConnected guard: mobile rebuilds this element on track changes (see slot_id note above), so a rebuild landing before this rAF fires would otherwise animate a disconnected ghost. Skipping lets the rebuilt element's own fresh eval retry the entrance correctly.
      if (!card || !card.isConnected) return;
      store._npKey = key;
      try { store._npBodyAnim?.cancel(); } catch (e) {}

      const clearStamp = () => {
        card.style.removeProperty('transform');
        card.style.removeProperty('opacity');
      };

      if (skipFirst) { clearStamp(); return; }

      if (isExit) {
        clearStamp();
        if (horizontal) {
          card.style.transformOrigin = '50% 50%';
          store._npBodyAnim = card.animate(
            [
              { opacity: 1, transform: 'translateX(0px)' },
              { opacity: 0, transform: 'translateX(40px)' },
            ],
            { duration: 320, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'both' }
          );
        } else {
          card.style.transformOrigin = '50% 0%';
          store._npBodyAnim = card.animate(
            [
              { opacity: 1, transform: 'scale(1, 1)' },
              { opacity: 0, transform: 'scale(0.78, 0.06)' },
            ],
            { duration: 320, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'both' }
          );
        }

        store._npBodyAnim.finished
          .then(() => { try { store._npBodyAnim?.cancel(); } catch (e) {} })
          .catch(() => {});
        return;
      }

      // One small overshoot and settle - two overshoots read as wobble.
      const R = 26;

      clearStamp();

      if (horizontal) {
        const rectScope = String(variables.slot_id || '')
          .replace(/\|np\d+$/, '');
        const priorRect = (window._hemmaNPRowRects || {})[rectScope + '|' + key];
        if (priorRect && tr.width > 4 && tr.height > 4) {
          const sx = priorRect.width  / tr.width;
          const sy = priorRect.height / tr.height;
          const dx = (priorRect.left + priorRect.width  / 2) - (tr.left + tr.width  / 2);
          const dy = (priorRect.top  + priorRect.height / 2) - (tr.top  + tr.height / 2);
          card.style.transformOrigin = '50% 50%';
          store._npBodyAnim = card.animate(
            [
              { transform: `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px) scale(${sx.toFixed(4)}, ${sy.toFixed(4)})`, opacity: 1 },
              { transform: 'translate(0px, 0px) scale(1, 1)', opacity: 1 },
            ],
            { duration: 460, easing: 'cubic-bezier(0.25, 0.9, 0.3, 1)', fill: 'both' }
          );
          store._npBodyAnim.finished
            .then(() => { try { store._npBodyAnim?.cancel(); } catch (e) {} })
            .catch(() => {});
          return;
        }

        card.style.transformOrigin = '50% 50%';
        store._npBodyAnim = card.animate(
          [
            { opacity: 0, transform: 'translateX(40px)' },
            { opacity: 1, transform: 'translateX(-4px)', offset: 0.75 },
            { opacity: 1, transform: 'translateX(0px)' },
          ],
          { duration: 460, easing: 'cubic-bezier(0.25, 0.9, 0.3, 1)', fill: 'both' }
        );
        store._npBodyAnim.finished
          .then(() => { try { store._npBodyAnim?.cancel(); } catch (e) {} })
          .catch(() => {});
        return;
      }

      card.style.opacity = '0';
      const artUrl = variables.hold_src?.art;
      const reveal = () => {
        card.style.transformOrigin = '50% 50%';
        card.style.removeProperty('opacity');
        store._npBodyAnim = card.animate(
          [
            { opacity: 0 },
            { opacity: 1 },
          ],
          { duration: 420, easing: 'ease-out', fill: 'both' }
        );
        store._npBodyAnim.finished
          .then(() => { try { store._npBodyAnim?.cancel(); } catch (e) {} })
          .catch(() => {});
      };
      if (artUrl) {
        let artDone = false;
        const proceed = () => { if (artDone) return; artDone = true; reveal(); };
        const img = new Image();
        img.onload = proceed;
        img.onerror = proceed;
        img.src = artUrl;
        setTimeout(proceed, 400);
      } else {
        reveal();
      }
    });
  }

  // Publishes this slot's resting rect so a future reassignment knows where to FLIP from.
  if (horizontal && key) {
    requestAnimationFrame(() => {
      const el = this;
      if (!el) return;
      const r = el.getBoundingClientRect();
      if (r.width > 4 && r.height > 4) {
        window._hemmaNPRowRects = window._hemmaNPRowRects || {};
        window._hemmaNPRowRects[
          String(variables.slot_id || '').replace(/\|np\d+$/, '')
          + '|' + key] = r;
      }
    });
  }


  return key ? 1 : 0;
]]]

card.--np-accent:
[[[
  const k = variables.hold_src?.kind;
  if (k === 'plex') return 'var(--hemma-color-orange, #FF9230)';
  if (k === 'activity') return 'var(--hemma-color-blue, #0A84FF)';
  return 'var(--hemma-color-teal, #00c3d0)';
]]]

card.--hemma-badge-body-tint:
[[[
  const isDark = typeof hass?.themes?.darkMode === 'boolean'
    ? hass.themes.darkMode
    : window.matchMedia('(prefers-color-scheme: dark)').matches;
  const v = isDark ? '0.25' : '0.05';
  // Also sets --np-scrim-mult here (avoids a second hass.themes read): ha-card::after's readability scrim needs its own dark-mode scaling, uncoupled from this tint.
  try { this.style.setProperty('--np-scrim-mult', isDark ? '1' : '0.55'); } catch (e) {}
  return v;
]]]

grid.grid-template-rows:
[[[
  const c = variables.hold_src?.controls;
  const hasControls = !!(c && (c.toggle || c.next || c.prev))
    && (variables.np_count || 1) <= 2;
  return hasControls ? 'max-content max-content' : 'max-content 0px';
]]]

grid.row-gap:
[[[
  const c = variables.hold_src?.controls;
  return (c && (c.toggle || c.next || c.prev)) && (variables.np_count || 1) <= 2
    ? 'var(--np-row-gap, 8px)' : '0px';
]]]

name.align-self:
[[[
  const c = variables.hold_src?.controls;
  const hasControls = !!(c && (c.toggle || c.next || c.prev))
    && (variables.np_count || 1) <= 2;
  return hasControls ? 'end' : 'center';
]]]

hemma_now_playing_primary.name:
[[[
  const s = variables.hold_src;
  if (!s) return '';

  const esc = (t) => String(t ?? '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  const bits = s.kind === 'player'
    ? [s.subtitle]
    : [s.source, s.subtitle];
  const sub = bits.map(x => String(x || '').trim()).filter(Boolean).join(' · ');

  let bar = '';
  if ((variables.np_count || 1) <= 3
    && Number.isFinite(s.dur) && s.dur > 0 && Number.isFinite(s.pos)) {
    const elapsed = s.playing && s.posAt ? (Date.now() - s.posAt) / 1000 : 0;
    const now = Math.min(s.dur, Math.max(0, s.pos + elapsed));
    const frac = Math.max(0, Math.min(1, now / s.dur));
    const remain = Math.max(0, s.dur - now);
    const anim = s.playing && remain > 0
      ? `animation: np-advance ${remain.toFixed(1)}s linear forwards;`
      : '';
    bar = `<div class="np-track"><div class="np-fill" style="transform: scaleX(${frac.toFixed(5)}); ${anim}"></div></div>`;
  }

  // The progress bar makes this markup new on every render, which rebuilds the lines: a scrolling one is written
  // already scrolling, at the point its scroll had reached (--np-marquee-scan keeps the start time).
  const mq = this._npMq || {};
  const line = (cls, text) => {
    const m = mq[cls + '|' + text];
    if (!m) return `<div class="np-line"><span class="${cls}">${esc(text)}</span></div>`;
    const at = (m.base - (Date.now() - m.t0) / 1000).toFixed(2);
    return `<div class="np-line np-scroll" style="--np-mq:${m.mq};--np-marquee-dur:${m.dur};--np-mq-delay:${at}s">`
      + `<span class="${cls}">${esc(text)}</span>`
      + `<span class="${cls} np-marquee-clone" aria-hidden="true" style="margin-left:${m.gap}px">${esc(text)}</span></div>`;
  };
  return `
    <div class="np-meta">
      ${line('np-title', s.title)}
      ${sub ? line('np-sub', sub) : ''}
      ${bar}
    </div>
  `;
]]]

hemma_now_playing_primary.extra_styles:
:host{
  display: block;
  /* :host must track ha-card's capped width - the glass rim is :host::after (inset:0), so a flat 100% host let the rim draw wider than ha-card's own max-width on wide tracks. margin-left:auto keeps the pair right-aligned. */
  /* !important: button-card inline-clamps the host to max-width:fit-content whenever styles.card carries a width key (see hemma_mobile_now_playing.yaml), beating a plain :host rule. */
  width: var(--np-tile-width, 100%) !important;
  max-width: var(--np-max-w, calc(var(--hemma-u-np, 10px) * 40)) !important;
  margin-left: auto;
  --np-shadow: none;

  /* Artwork can't shrink below the text column height, or the column drives card height and breaks the equal insets - so column height is trimmed and the freed space goes to padding. */
  /* min(natural, slot): --np-slot-h is the stack's budget split between the live
     tiles, so one or two keep their natural size and the rest shrink exactly
     enough to fit. The 999px fallback is the mobile row, which sets no slot. */
  /* The phone's tile on every device: the artwork sets the height, the text and transport sit within it. */
  --np-pad-v: min(16px, calc(var(--np-slot-h, 999px) * 0.134));
  /* Top and bottom match the left: the glass rim along them already makes those bands read thinner. */
  --np-pad-tb: min(16px, calc(var(--np-slot-h, 999px) * 0.134));
  --np-art-size: min(108px, calc(var(--np-slot-h, 999px) - 2 * var(--np-pad-tb)));
  --np-row-gap: 7px;
  --np-track-gap: 9px;
  /* Desktop's title/sub read as loud as the entity grid's own tile names despite living in a peripheral,
     ambient corner widget — sized down a step so it reads as glanceable status, not a second headline. */
  /* Also min(): past five tiles the text column, not the artwork, is what
     would drive the card past its slot. */
  --np-title-size: min(16px, calc(var(--np-slot-h, 999px) * 0.30));
  --np-sub-size: min(14px, calc(var(--np-slot-h, 999px) * 0.26));
}

/* Minimise/expand motion, lifted from hemma_badge_base's entrance with the origin moved to the header's waveform toggle.
   Lives on ha-card because it's the element carrying the backdrop-filter — animating any ancestor moves the backdrop root up and the tile spends the animation sampling an empty layer (see hemma_badge_base's `translate` note).
   Uses translate/scale (not transform) so --np-swap's WAAPI transform animations compose instead of clobbering these mid-swap. */
:host{
  --np-enter-t: calc(1 - var(--np-min, 0));
  --np-enter-p: var(--np-min, 0);
  /* Was a 30px shift, a 20px lift and a 0.22 depth with a 0.07 squash -
     a droplet flying to the toggle. The refined motion is a uniform scale
     in place, so the shift and the squash are gone and the depth is what
     reads as a settle rather than a flight. Reduced motion takes this path
     on its own, so it has to say the same thing as the keyframes. */
  --np-enter-shift: 0px;
  --np-enter-lift: 0px;
  --np-enter-depth: 0.08;
  --np-enter-squash: 0;
  --np-enter-dur: calc(0.34s + var(--np-enter-t) * 0.14s);
  --np-enter-fade: calc(0.20s + var(--np-enter-t) * 0.05s);
  --np-enter-ease: cubic-bezier(0.34, 1.26, 0.44, 1);
}

ha-card{
  /* Real CSS enforcement of --np-max-w (see styles.card comment for why). */
  max-width: var(--np-max-w, calc(var(--hemma-u-np, 10px) * 40)) !important;
  transform-origin: 100% 0%;
  translate:
    calc(var(--np-enter-p) * var(--np-enter-shift))
    calc(var(--np-enter-p) * var(--np-enter-lift));
  scale:
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) - var(--np-enter-squash)))
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) + var(--np-enter-squash)));
  opacity: calc(var(--np-enter-t, 1) * var(--np-has-src, 1));
  /* Empty tile shouldn't stay tappable - it still occupies its slot until the row drops it. */
  pointer-events: var(--np-src-ptr, auto);
  cursor: pointer;
  transition: none !important;
  /* translate/scale/opacity above are the RESTING state only - the WAAPI spring (driven by the shell's --np-min) owns the motion, so they're deliberately excluded from this transition list. */
  transition-property: backdrop-filter, -webkit-backdrop-filter !important;
  transition-duration: .15s !important;
  transition-timing-function: ease !important;
}

/* Only :host::after gets this copy - #container::before is inside ha-card and already inherits its scale as an ancestor, so adding the same transform again would square it. */
:host::after{
  transform-origin: 100% 0%;
  translate:
    calc(var(--np-enter-p) * var(--np-enter-shift))
    calc(var(--np-enter-p) * var(--np-enter-lift));
  scale:
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) - var(--np-enter-squash)))
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) + var(--np-enter-squash)));
  /* No transition: shell drives this via the same WAAPI keyframes (pseudoElement) as ha-card, so rim/specular spring together. */
}

ha-ripple, mwc-ripple { display: none !important; }

:host{
  --hemma-card-hover-shadow: var(--np-shadow);
  --hemma-card-hover-filter: none;
}

/* Poster - same declarative binding the bloom above uses (--np-art), just sharp instead of blurred. */
.np-art-img{
  position: absolute;
  inset: 0;
  background-image: var(--np-art, none);
  background-size: cover;
  background-position: center;
  background-color: rgba(255,255,255,0.08);
}

#art::after{
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 0.5px rgba(255,255,255,0.12);
}

/* Artwork bloom */
ha-card::before{
  content: '';
  position: absolute;
  inset: -40%;
  z-index: 0;
  background-image: var(--np-art, none);
  background-size: cover;
  background-position: center;
  filter: blur(52px) saturate(150%);
  opacity: calc(var(--np-has-art, 0) * var(--np-bloom-strength, 0.30) * var(--np-reveal, 1) * var(--hv-np-bloom, 1));
  transform: translateZ(0);
  pointer-events: none;
  transition: opacity .45s ease;
}

/* Readability scrim. --np-scrim-mult (set alongside --hemma-badge-body-tint above) scales it down in light mode. */
ha-card::after{
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(105deg,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.42 * var(--np-scrim-mult, 1))) 0%,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.16 * var(--np-scrim-mult, 1))) 62%,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.30 * var(--np-scrim-mult, 1))) 100%);
  opacity: calc(var(--np-reveal, 1) * var(--hv-np-scrim, 1));
  pointer-events: none;
}

/* Glass surface */
:host::after{
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  z-index: 6;
  --np-rim-side:      var(--hemma-badge-rim-side-blur, 2px) var(--hemma-badge-rim-side-spread, -1px) rgba(0,0,0,var(--hemma-badge-rim-side, 0.98));
  --np-rim-bottom:    0 1px 1px -1px rgba(0,0,0,var(--hemma-badge-rim-bottom, 0.14));
  --np-rim-top:       0 -1px 1px -1px rgba(0,0,0,var(--hemma-badge-rim-top, 0.12));
  /* ── BOTTOM DROP SHADOW ── the same token the dropdowns float on, so the
     tile and a menu opened beside it cannot read as two different heights.
     Tune the whole shadow with --np-elevation, or `none` to remove it. */
  --np-rim-elevation: var(--np-elevation,
    var(--hemma-elevation-floating, 0 8px 20px rgba(0,0,0,0.13)));
  box-shadow:
    var(--hemma-badge-rim-side-offset, 1px) 0 var(--np-rim-side),
    calc(-1 * var(--hemma-badge-rim-side-offset, 1px)) 0 var(--np-rim-side),
    var(--np-rim-bottom),
    var(--np-rim-top),
    var(--np-rim-elevation);
  /* --np-has-src as well, exactly as ha-card does it. This pseudo is on the
     HOST, outside the card, so the card fading out left the rim and its
     drop shadow still painting. One tile per panel never showed it; a stack
     of seven with six empty drew six empty rectangles. */
  opacity: calc(var(--np-glass, 1) * var(--np-enter-t, 1) * var(--np-has-src, 1) * var(--np-reveal, 1) * var(--hv-np-glass, 1));
}

/* Specular ring + inner hairline - ONE pseudo-element. These used to be two separate #container::before
   rule blocks; an element can only have one ::before, so CSS was merging them property-by-property, and
   the second block's mismatched border-radius (17px, vs. --np-inner-radius elsewhere) silently won over
   the first — which is exactly why the hairline's straight edge stopped short of the card's actual
   (26px) rounded corner instead of tracing it. Merged so both layers share the real radius, and the
   hairline's box-shadow now rides the same top-to-bottom mask as the ring — which is also the fix for
   "the highlight should fade out as it curves around the corner" rather than cutting off. */
#container::before{
  content: '';
  position: absolute;
  /* Inset tracks --np-pad-tb/--np-pad-v (not hardcoded) so this reaches the card's true edge as padding changes; right stays literal -16px matching the padding shorthand. */
  inset: calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) -16px
         calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) calc(-1 * var(--np-pad-v, 16px));
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  pointer-events: none;
  z-index: 5;
  padding: var(--hemma-badge-ring-thickness, 1.3px);
  backdrop-filter: var(--hemma-badge-ring-backdrop, brightness(var(--hemma-badge-ring-boost, 1.5)) saturate(var(--hemma-badge-ring-sat, 1.8)));
  -webkit-backdrop-filter: var(--hemma-badge-ring-backdrop, brightness(var(--hemma-badge-ring-boost, 1.5)) saturate(var(--hemma-badge-ring-sat, 1.8)));
  mix-blend-mode: screen;
  box-shadow:
    inset 0 0.5px 0 rgba(255,255,255,0.34),
    inset 0 0 0 0.5px rgba(255,255,255,0.10),
    inset 0 -0.5px 0 rgba(255,255,255,0.10);
  -webkit-mask:
    linear-gradient(to bottom,
      rgba(0,0,0,.5) 0%,
      rgba(0,0,0,0.15) 32%,
      rgba(0,0,0,0) 45%,
      rgba(0,0,0,0) 55%,
      rgba(0,0,0,0.07) 68%,
      rgba(0,0,0,0.05) 100%),
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: source-in, xor;
          mask-composite: intersect, exclude;
  opacity: calc(var(--np-glass, 1) * var(--np-reveal, 1) * var(--hv-np-glass, 1));
  transform: translateZ(0);
  backface-visibility: hidden;
}

#container{
  opacity: var(--np-reveal, 1);
  position: relative;
  z-index: 2;
  /* button-card's shadow DOM makes this a flex/grid child of ha-card (default min-width:auto refuses to shrink below content) - without this, an unwrapped long title could grow ha-card past its max-width caps. */
  min-width: 0;
}

/* Hover tint */
#container::after{
  content: '';
  position: absolute;
  inset: calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) -16px
         calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) calc(-1 * var(--np-pad-v, 16px));
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  pointer-events: none;
  z-index: 5;
  background: rgba(255,255,255,0.05);
  opacity: 0;
  transition: opacity .40s ease;
}

@media (hover: hover) {
  ha-card:hover #container::after{
    opacity: 0.6;
    transition: opacity .18s ease;
  }
}

.np-meta{
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.np-title{
  font-size: var(--np-title-size, 16px);
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 1.15;
  color: var(--hv-np-ink, var(--primary-text-color, #fff));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  /* overflow clips at the padding box, or descenders lose their tails. */
  padding-block: 0.16em;
  margin-block: -0.16em;
}

.np-sub{
  font-size: var(--np-sub-size, 14px);
  font-weight: 400;
  letter-spacing: -0.1px;
  line-height: 1.18;
  color: var(--hv-np-sub2, var(--hemma-np-sub, rgba(255,255,255,0.62)));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding-block: 0.16em;
  margin-block: -0.16em;
}

.np-track{
  margin-top: var(--np-track-gap, 12px);
  height: calc(var(--hemma-u-np, 10px) * 0.4);
  border-radius: 999px;
  background: var(--hv-np-track2, var(--hemma-np-track, rgba(255,255,255,0.16)));
  overflow: hidden;
}

.np-fill{
  height: 100%;
  width: 100%;
  border-radius: 999px;
  background: var(--hv-np-fill, var(--np-accent, #67f5a0));
  transform-origin: left center;
}

.np-line{
  overflow: hidden;
  min-width: 0;
  /* Otherwise the card's font sets each line's height, opening the title to artist gap too wide. */
  line-height: 0;
}

.np-line > .np-title,
.np-line > .np-sub{
  display: inline-block;
  max-width: none;
}

/* Right fade only at rest - left fade animates in separately below (avoids dimming the first char before it's actually scrolled). */
.np-line.np-scroll{
  -webkit-mask-image: linear-gradient(90deg,
    #000 0px, #000 calc(100% - 18px), transparent 100%);
  mask-image: linear-gradient(90deg,
    #000 0px, #000 calc(100% - 18px), transparent 100%);
  animation: np-marquee-fade var(--np-marquee-dur, 12s) linear infinite;
  animation-delay: var(--np-mq-delay, 0s);
}

/* Offsets (0-12%, 24-100%) match np-marquee's own pause window below - keep them synced if either changes. */
@keyframes np-marquee-fade{
  0%, 12%{
    -webkit-mask-image: linear-gradient(90deg,
      #000 0px, #000 0px, #000 calc(100% - 18px), transparent 100%);
    mask-image: linear-gradient(90deg,
      #000 0px, #000 0px, #000 calc(100% - 18px), transparent 100%);
  }
  24%, 100%{
    -webkit-mask-image: linear-gradient(90deg,
      transparent 0px, #000 7px, #000 calc(100% - 18px), transparent 100%);
    mask-image: linear-gradient(90deg,
      transparent 0px, #000 7px, #000 calc(100% - 18px), transparent 100%);
  }
}

.np-marquee-clone{
  display: inline-block;
}

.np-line.np-scroll > .np-title,
.np-line.np-scroll > .np-sub{
  animation: np-marquee var(--np-marquee-dur, 12s) linear infinite;
}

.np-line.np-scroll > .np-title,
.np-line.np-scroll > .np-sub{
  animation-delay: var(--np-mq-delay, 0s);
}

@keyframes np-marquee{
  0%,  12% { transform: translateX(0); }
  100%     { transform: translateX(calc(-1 * var(--np-mq, 0px))); }
}

@media (prefers-reduced-motion: reduce){
  .np-line.np-scroll > .np-title,
  .np-line.np-scroll > .np-sub{ animation: none !important; }
  .np-line.np-scroll{
    animation: none !important;
    -webkit-mask-image: none;
    mask-image: none;
  }
  .np-marquee-clone{ display: none; }
}

@keyframes np-advance { to { transform: scaleX(1); } }

@media (prefers-reduced-motion: reduce) {
  .np-fill{ animation: none !important; }
}

/* Mobile */
@media (max-width: 600px){
  :host{
    /* 108 not 100: art must stay ≥ text column height (~107px with 44px transport) or the column drives card height. */
    --np-art-size: 108px;
    --np-title-size: 16px;
    --np-sub-size: 14px;
    --np-pad-v: 16px;
    --np-row-gap: 7px;
    --np-track-gap: 9px;
    /* Lower than desktop: tiles are usually darker than the wallpaper, so full elevation reads as haze. */
    --np-elevation: 0 1px 6px rgba(0,0,0,0.10);
    /* Phone slots are sized by the row itself, so the desktop cap and right-align both come off here. */
    max-width: 100% !important;
    margin-left: 0;
  }
}

/* Phone landscape. Without this the tile fell through EVERY breakpoint - 932px wide fails the
   mobile query's max-width:600px, and 430px tall fails the tablet query's min-height:501px — so
   it silently used the desktop defaults (94px art, 16px padding, 15px title) on the shortest
   viewport there is. Same condition the theme uses for phone landscape.
   --np-pad-tb is restated deliberately: it is set unconditionally on :host, so it does NOT
   inherit this block's --np-pad-v (see the note on the desktop declaration). */
@media (hover: none) and (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  :host{
    --np-art-size: 112px;
    --np-title-size: 16px;
    --np-sub-size: 14px;
    --np-pad-v: 12px;
    --np-pad-tb: 12px;
    --np-row-gap: 5px;
    --np-track-gap: 6px;
    --np-elevation: 0 1px 6px rgba(0,0,0,0.10);
    /* Slot width is owned by the row, as on portrait mobile. */
    max-width: 100% !important;
    margin-left: 0;
  }
}

hemma_camera_alert_helper.value:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  if (typeof window.hemmaCameraAlert !== 'function') {
    /* Ring publishes ding/motion as event.* entities whose state is the
       timestamp of the last one, so "recent" is the whole alert model.
       Reading sensor.time subscribes the caller to the minute tick, which
       is what lets a stale alert expire without another camera event. */
    window.hemmaCameraAlert = function (hass, states, cams, windowMinutes) {
      const reg = (hass && hass.entities) || {};
      const devs = {};
      cams.forEach(function (id) {
        const d = reg[id] && reg[id].device_id;
        if (d) devs[d] = true;
      });
      const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
      const now = Date.now();
      states['sensor.time'];
      let ding = false, motion = false;
      Object.keys(reg).forEach(function (id) {
        if (id.indexOf('event.') !== 0) return;
        if (!devs[reg[id].device_id]) return;
        const t = Date.parse(states[id] && states[id].state);
        if (!isFinite(t) || now - t > span) return;
        if (/ding|doorbell|button/.test(id)) ding = true;
        else if (/motion/.test(id)) motion = true;
      });
      return ding ? T('cameras.doorbell', 'Doorbell') : motion ? T('cameras.motion_detected', 'Motion Detected') : '';
    };
  }
  return true;
]]]

