hemma_battery.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const list = variables.batteries || variables.entity_filter;
  const batteries = (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).filter(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    if (isNaN(parseFloat(e.state))) return false;
    return e.attributes.device_class === 'battery';
  });
  if (batteries.length === 0) return T('battery.no_sensors', 'No Sensors');
  const anyLow = batteries.some(e => parseFloat(e.state) <= 20);
  return anyLow ? T('state.needs_attention', 'Needs Attention') : T('state.healthy', 'Healthy');
]]]

state.value:
[[[
  const list = variables.batteries || variables.entity_filter;
  return (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).some(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    const pct = parseFloat(e.state);
    if (isNaN(pct)) return false;
    return e.attributes.device_class === 'battery' && pct <= 20;
  });
]]]

hemma_cameras.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const cams = Array.isArray(variables.cameras) ? variables.cameras.filter(Boolean) : [];
  if (!cams.length) return T('cameras.none', 'No Cameras');
  const dead = cams.filter(id => ['unavailable','unknown',''].includes(String(states[id]?.state ?? '').toLowerCase())).length;
  if (dead === cams.length) return cams.length === 1 ? T('cameras.offline', 'Offline') : T('cameras.all_offline', 'All Offline');
  if (dead > 0) return T('cameras.n_offline', '{n} Offline', { n: dead });
  const alert = window.hemmaCameraAlert ? window.hemmaCameraAlert(hass, states, cams, variables.alert_window_minutes) : '';
  return alert || T('cameras.no_alerts', 'No Alerts');
]]]

