    automation: 'scenes', button: 'power_on', input_button: 'power_on',
    binary_sensor: 'person-walking-motion', remote: 'tv', water_heater: 'hot_water',
    valve: 'curtain-open', siren: 'person-walking-motion',
  })[dom] || 'default';
]]]

