hemma_light.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const memsOf = (eid) => {
    const m = states[eid]?.attributes?.entity_id;
    return Array.isArray(m) ? m.filter(x => typeof x === "string" && x.startsWith("light.")) : [];
  };
  const units = (eid, seen) => {
    if (!eid || seen.has(eid)) return [];
    const mems = memsOf(eid);
    // No members, or no member is itself a group -> one physical light.
    if (!mems.length || !mems.some(m => memsOf(m).length)) return [eid];
    seen.add(eid);
    return mems.flatMap(m => units(m, seen));
  };

  // A lamp group shown as one light inside its room (variables.as_light) reads as one light: its own brightness.
  if (entity && (variables.as_light || !memsOf(entity.entity_id).length)) {
    const b = Number(entity.attributes?.brightness);
    if (entity.state === 'on' && b > 0) return Math.max(1, Math.round((b / 255) * 100)) + '%';
    return hass.formatEntityState ? hass.formatEntityState(entity) : entity.state;
  }
  const seen = new Set();
  const all = [...new Set(units(entity?.entity_id, seen))];
  const onCount = all.filter(eid => states[eid]?.state === "on").length;

  return onCount === 0 ? T('lights.all_off', 'All Off')
       : onCount === all.length ? T('lights.all_on', 'All On')
       : T('lights.n_on', '{n} On', { n: onCount });
]]]

variables.open_doors:
[[[
  const m = variables.door_sensors || {};
  const ids = [...new Set([].concat(variables.locks || [], entity ? [entity.entity_id] : []).filter(Boolean))];
  return [...new Set(ids.flatMap((id) => [].concat(m[id] || [])))].filter((s) => states[s]?.state === 'on').length;
]]]

