variables.is_active:
[[[
  const s = String(entity?.state || '').toLowerCase();
  if (s === 'playing') return true;
  const extra = Array.isArray(variables.active_states) ? variables.active_states.map(v => String(v).toLowerCase()) : [];
  return extra.includes(s);
