variables.has_artwork:
[[[
  if (String(entity?.state || "").toLowerCase() !== "playing") return false;
  const a = entity?.attributes || {};
  const id = entity?.entity_id || '';
  const type = String(a.media_content_type || '').toLowerCase();
  const app = String(a.app_name || '').trim();
  const title = (a.media_title || a.title || '').trim();
  const source = (a.source || a.media_channel || '').trim();
  const isSonos = id.includes('sonos') || (a.friendly_name || '').toLowerCase().includes('sonos');
  const bareInputs = ['tv','hdmi','arc','hdmi arc','optical','line-in','line in'];
  let looksLikeBareInput = false;
  if (isSonos && title) {
    const tLow = title.toLowerCase();
    looksLikeBareInput = bareInputs.includes(tLow) || (!!source && tLow === source.toLowerCase());
  }
  const isYouTube = app.toLowerCase().includes('youtube');
  const pic = isYouTube
    ? (states['sensor.youtube_watching']?.attributes?.thumbnail || a.entity_picture || '')
    : (a.entity_picture || '');
  const hasRichMeta = !!(a.media_series_title || a.media_episode_title);
  const fromRichApp = /youtube|plex|netflix|hulu|disney|max|prime|spotify|apple tv|apple music|paramount|peacock/i.test(app);
  return !!pic && !looksLikeBareInput && (hasRichMeta || ['music','movie','video','tvshow','game'].includes(type) || fromRichApp);
]]]

variables.art_url:
[[[
  const a = entity?.attributes || {};
  const isYouTube = String(a.app_name || '').toLowerCase().includes('youtube');
  const pic = isYouTube
    ? (states['sensor.youtube_watching']?.attributes?.thumbnail || a.entity_picture || '')
    : (a.entity_picture || '');
  if (!pic) return '';
  return pic.startsWith('/') ? window.location.origin + pic : pic;
]]]

hemma_media.entity_picture:
[[[
  if (variables.has_artwork && variables.art_url) return variables.art_url;
  const icon = variables?.icon;
  if (icon === 'ps5') {
    if (document.documentElement.classList.contains('hemma-hv')) return window.hemmaIconUrl('playstation');
    if (variables.is_active) {
      return `${window.hemmaIconUrl('ps5')}#s=${encodeURIComponent(entity.last_changed || '')}`;
    }
    return window.hemmaIconUrl('ps5_off');
  }
  if (icon) return window.hemmaIconUrl(icon);
  return window.hemmaIconUrl('speaker');
]]]

hemma_media.state_display:
[[[
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  const sRaw = String(entity?.state || "");
  const s    = sRaw.toLowerCase();
  const a    = entity?.attributes || {};
  const cap  = (x) => (x ? x.charAt(0).toUpperCase() + x.slice(1) : "");
  const esc  = (t) => String(t ?? "")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .trim();
  if (s === "playing") {
    const id       = entity?.entity_id || "";
    const friendly = (a.friendly_name || "").toLowerCase();
    const type   = String(a.media_content_type || "").toLowerCase();
    const title  = (a.media_title || a.title || "").trim();
    const artist =
      (a.media_artist || a.artist || a.media_album_artist || "").trim();
    const app    = (a.app_name || "").trim();
    const source = (a.source || a.media_channel || "").trim();
    const isMusic =
      type === "music" ||
      id.includes("spotify") ||
      (!!artist && !["movie","video","tvshow"].includes(type));
    let label = "";
    if (isMusic) {
      if (artist && title) label = `${artist} - ${title}`;
      else label = title || artist || app || source || L('component.media_player.entity_component._.state.' + s, cap(s));
    } else {
      label = title || app || source || L('component.media_player.entity_component._.state.' + s, cap(s));
    }
    const isSonos = id.includes("sonos") || friendly.includes("sonos");
    const bareInputs = ["tv","hdmi","arc","hdmi arc","optical","line-in","line in"];
    let looksLikeBareInput = false;
    if (isSonos) {
      const tLow = title.toLowerCase();
      const sLow = source.toLowerCase();
      if (
        title && (
          bareInputs.includes(tLow) ||
          (source && tLow === sLow)
        )
      ) {
        looksLikeBareInput = true;
      }
    }
    const hasRichMeta =
      !!(a.media_artist || a.media_album_artist || a.media_series_title || a.media_episode_title);
    const mediaTypes = ["music","movie","video","tvshow","game"];
    const fromRichApp =
      /youtube|plex|netflix|hulu|disney|max|prime|spotify|apple tv|apple music|paramount|peacock/i
        .test(app);
    const isRichPlayback = !looksLikeBareInput && (
      hasRichMeta ||
      mediaTypes.includes(type) ||
      fromRichApp
    );
    if (!isRichPlayback) return esc(label) || L('component.media_player.entity_component._.state.' + s, cap(s));
    return `<span class="hemma-media-state">${esc(label)}</span>`;
  }
  if (["off","idle","paused","standby","unavailable","unknown"].includes(s)) {
    return L('component.media_player.entity_component._.state.' + s, cap(s));
  }
  return s ? L('component.media_player.entity_component._.state.' + s, cap(s)) : L('component.media_player.entity_component._.state.off', 'Off');
]]]

