hemma_plant.state_display:
[[[
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  if (!entity?.state || entity.state === 'unavailable') return '— %';

  if (entity.state === 'ok') return T('state.healthy', 'Healthy');

  const sensors = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];

  if (sensors.length > 0 && entity.state === 'problem') {
    const safeNum = (id) => {
      const s = states[id]?.state;
      if (!s || s === 'unavailable' || s === 'unknown') return null;
      const n = parseFloat(s);
      return isNaN(n) ? null : n;
    };
    const getSensorType = (eid) => {
      const id = eid.toLowerCase();
      if (id.includes('moisture'))                       return 'moisture';
      if (id.includes('illumin') || id.includes('lux')) return 'illuminance';
      if (id.includes('temp'))                           return 'temperature';
      if (id.includes('conductiv'))                      return 'conductivity';
      if (id.includes('humid'))                          return 'humidity';
      return null;
    };
    const attrs    = entity.attributes || {};
    const scorable = sensors.filter(id => { const t = getSensorType(id); return t && Object.prototype.hasOwnProperty.call(attrs, t + '_status'); });
    const scored   = scorable.filter(id => safeNum(id) != null);

    if (scorable.length > 0 && scored.length === 0) return L('state.default.unavailable', 'Unavailable');

    if (scored.length > 0) {
      const bad   = scored.filter(id => { const v = attrs[getSensorType(id) + '_status']; return v && v !== 'ok' && v !== 'null'; }).length;
      const ratio = (scored.length - bad) / scored.length;
      if (ratio >= 1)   return T('state.healthy', 'Healthy');
      if (ratio >= 0.8) return T('plant.needs_care', 'Needs care');
      if (ratio >= 0.6) return T('plant.struggling', 'Struggling');
      if (ratio >= 0.4) return T('plant.poor', 'Poor');
      return T('plant.critical', 'Critical');
    }
  }

  if (entity.state === 'problem') return T('state.needs_attention', 'Needs Attention');

  const val = parseFloat(entity.state);
  if (!Number.isNaN(val)) return `${Math.round(val)} %`;

  const attr = parseFloat(entity.attributes?.moisture);
  if (!Number.isNaN(attr)) return `${Math.round(attr)} %`;
  return '— %';
]]]

state.value:
[[[
  if (entity?.state === 'problem') return true;
  if (entity?.state === 'ok') return false;

  const sensors = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];
  if (sensors.length > 0) {
    const safeNum = (id) => {
      const s = states[id]?.state;
      if (!s || s === 'unavailable' || s === 'unknown') return null;
      const n = parseFloat(s);
      return isNaN(n) ? null : n;
    };
    const getSensorType = (eid) => {
      const id = eid.toLowerCase();
      if (id.includes('moisture'))                       return 'moisture';
      if (id.includes('illumin') || id.includes('lux')) return 'illuminance';
      if (id.includes('temp'))                           return 'temperature';
      if (id.includes('conductiv'))                      return 'conductivity';
      if (id.includes('humid'))                          return 'humidity';
      return null;
    };
    const attrs = entity?.attributes || {};
    const hasProblems = sensors.some(id => {
      if (safeNum(id) == null) return false;
      const type = getSensorType(id);
      if (!type) return false;
      const v = attrs[type + '_status'];
      return v && v !== 'ok' && v !== 'null';
    });
    if (hasProblems) return true;
  }

  const threshold = Number(variables.low_threshold ?? 30);
  const val = parseFloat(entity?.state);
  if (Number.isFinite(val)) return val <= threshold;
  const attr = parseFloat(entity?.attributes?.moisture);
  return Number.isFinite(attr) && attr <= threshold;
]]]

variables.idle:
[[[
  const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
  const items = (id) => {
    const d = states[id]?.attributes?.data;
    return Array.isArray(d) ? d.slice(1) : [];
  };
  return ![...items('sensor.recently_added_movies'), ...items('sensor.recently_added_tv')]
    .some(i => i && i.title && i.airdate && new Date(i.airdate).getTime() >= cutoff);
]]]

hemma_plex_recently_added.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const moviesData = states['sensor.recently_added_movies']?.attributes?.data;
  const tvData     = states['sensor.recently_added_tv']?.attributes?.data;
  const rawM = Array.isArray(moviesData) ? moviesData.slice(1).filter(i => i && i.title) : [];
  const rawT = Array.isArray(tvData)     ? tvData.slice(1).filter(i => i && i.title)     : [];
  const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
  const count = [...rawM, ...rawT].filter(i => i.airdate && new Date(i.airdate).getTime() >= cutoff).length;
  if (count <= 0) return T('plex.up_to_date', 'Up to date');
  return count === 1 ? T('plex.one_added', '1 Added') : T('plex.n_added', '{n} Added', { n: count });
]]]

state.value:
[[[
  const moviesData = states['sensor.recently_added_movies']?.attributes?.data;
  const tvData     = states['sensor.recently_added_tv']?.attributes?.data;
  const rawM = Array.isArray(moviesData) ? moviesData.slice(1).filter(i => i && i.title) : [];
  const rawT = Array.isArray(tvData)     ? tvData.slice(1).filter(i => i && i.title)     : [];
  const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
  const count = [...rawM, ...rawT].filter(i => i.airdate && new Date(i.airdate).getTime() >= cutoff).length;
  return count > 0;
]]]

