custom_fields.chrome_pill:
[[[
  const card = this;
  const bind = () => {
    const root = card.shadowRoot;
    if (!root) return requestAnimationFrame(bind);
    if (root._hemmaCapFlash) return;
    root._hemmaCapFlash = true;
    root.addEventListener('pointerdown', (ev) => {
      const pill = root.querySelector('#chrome_pill');
      const f = pill && pill.querySelector('.cp-flash');
      if (!f || !f.animate || !pill.getBoundingClientRect().width) return;
      const hit = ev.composedPath().some((n) => n && (['settings', 'assist', 'notifications'].indexOf(n.id) >= 0
        || (n.classList && n.classList.contains('np-head-wave'))));
      if (!hit) return;
      const r = pill.getBoundingClientRect();
      const x = Math.max(0, Math.min(100, ((ev.clientX - r.left) / r.width) * 100));
      f.style.background = 'radial-gradient(90px circle at ' + x.toFixed(1) + '% 50%,'
        + ' rgba(255,255,255,0.30) 0%, rgba(255,255,255,0.12) 55%, rgba(255,255,255,0) 100%)';
      f.animate([{ opacity: 0 }, { opacity: 1, offset: 0.25, easing: 'cubic-bezier(0.4,0,0.6,1)' }, { opacity: 0 }],
        { duration: 560, easing: 'ease-out' });
    }, true);
  };
  bind();
  // Each room has its own capsule, so a room change would swap widths in one frame.
  // The one leaving records its width; the one arriving grows or shrinks from it.
  if (!card._hemmaCapNav) {
    card._hemmaCapNav = true;
    const pillOf = () => {
      const pill = card.isConnected && card.shadowRoot && card.shadowRoot.querySelector('#chrome_pill');
      const w = pill ? pill.getBoundingClientRect().width : 0;
      return w ? { pill, w } : null;
    };
    window.addEventListener('location-changed', () => {
      const out = pillOf();
      if (out) window._hemmaCapPrev = out.w;
      requestAnimationFrame(() => requestAnimationFrame(() => {
        const now = pillOf();
        const prev = window._hemmaCapPrev;
        if (!now || out || !prev || Math.abs(prev - now.w) < 1 || !now.pill.animate) return;
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
        now.pill.animate([{ width: prev + 'px' }, { width: now.w + 'px' }],
          { duration: 240, easing: 'cubic-bezier(0.25, 0.8, 0.25, 1)' });
      }));
    });
  }
  return '<div class="cp-flash"></div>';
]]]

