    max-width: min(420px, 60vw);
  }
}

variables.has_controls:
[[[
  if (variables.size === 'large') return true;
  if (this?.classList?.contains('hemma-compact')) return false;
  return !window.matchMedia('(max-width: 767px) and (orientation: portrait), (max-height: 500px) and (orientation: portrait), (max-height: 600px) and (orientation: landscape)').matches;
]]]

variables.toggle_service_data:
[[[
  if (['cool','heat'].includes(entity?.state)) {
    return { entity_id: entity.entity_id, hvac_mode: 'off' };
  }
  return { entity_id: entity.entity_id, hvac_mode: states['input_select.hemma_thermostat_mode']?.state || 'cool' };
]]]

hemma_thermostat.state_display:
[[[
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const mode = entity?.state;
  const target = entity.attributes.temperature;
  if (mode === 'cool') {
    return T('thermostat.cooling_to', 'Cooling to {t}°', { t: target });
  } else if (mode === 'heat') {
    return T('thermostat.heating_to', 'Heating to {t}°', { t: target });
  } else {
    return L('component.climate.entity_component._.state.off', 'Off');
  }
]]]

custom_fields.temp_puck:
[[[
  let raw = entity?.attributes?.current_temperature;
  const eid = variables.temp_sensor;
  if (eid && states[eid] && !["unknown","unavailable"].includes(states[eid]?.state)) {
    raw = states[eid]?.state;
  }
  const n = Math.round(Number(raw));
  if (raw == null || Number.isNaN(n)) return '';

  const s = String(entity?.state || '').toLowerCase();
  const isCool = s === 'cool';
  const isHeat = s === 'heat';

  const circleBg = isCool
    ? '--hemma-icon-circle-bg:var(--hemma-puck-cool-color, #00d2e0);'
    : isHeat
      ? '--hemma-icon-circle-bg:var(--hemma-puck-heat-color, #ffd600);'
      : '';

  const eid2 = entity.entity_id;
  const stop = `event.stopPropagation();event.stopImmediatePropagation()`;
  const onMode = states['input_select.hemma_thermostat_mode']?.state || 'cool';
  const nextMode = ['cool','heat'].includes(entity?.state) ? 'off' : onMode;
  const smartToggle = `${stop};document.querySelector('home-assistant').hass.callService('climate','set_hvac_mode',{entity_id:'${eid2}',hvac_mode:'${nextMode}'})`;

  return `<div class="hemma-icon-circle" onpointerdown="${stop}" ontouchstart="${stop}" ontouchend="${smartToggle}" onclick="${smartToggle}" style="${circleBg}cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent;color:${circleBg ? 'rgba(255,255,255,0.9)' : 'var(--hemma-puck-num-off, rgba(255,255,255,0.9))'};font-weight:var(--hemma-puck-font-weight, 800);font-size:calc(var(--hemma-u, 10px) * 1.7);font-family:system-ui,-apple-system,sans-serif;">${n}</div>`;
]]]

hemma_thermostat.extra_styles:
/* Optical sizing: 800 is right at 17px, too heavy once the puck scales up.
   1740px is where --hemma-u leaves its floor, i.e. where the digits start growing. */
:host { --hemma-puck-font-weight: 800; }
@media (min-width: 1740px) { :host { --hemma-puck-font-weight: 700; } }

#temp_puck {
  grid-area: i !important;
  height: var(--hemma-icon-circle-size, 44px);
}

card_mod.style:
ha-card::after {
  transition: opacity var(--hemma-active-overlay-dur, .40s) ease, background-color .35s ease !important;
}
@media (hover: hover) {
  :host(:hover) ha-card::after {
    transition: opacity .18s ease, background-color .18s ease !important;
  }
  :host(:hover) ha-card {
    --hemma-active-overlay-opacity: var(--hemma-hover-overlay-opacity, 0.10);
    --hemma-entity-overlay-tint: var(--hemma-entity-hover-tint, rgba(255,255,255,0.55));
  }
}

variables.idle:
[[[
  const restart = Object.keys(states)
    .filter(id => id.startsWith('update.'))
    .some(id => {
      const e = states[id], a = (e && e.attributes) || {};
      return e && e.state === 'off'
        && a.installed_version && a.installed_version === a.latest_version
        && String(a.release_summary || '').toLowerCase().includes('restart');
    });
  const n = Number(entity?.state);
  return !(Number.isFinite(n) && n > 0) && !restart;
]]]

hemma_updates.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const restart = Object.keys(states)
    .filter(id => id.startsWith('update.'))
    .some(id => {
      const e = states[id], a = (e && e.attributes) || {};
      return e && e.state === 'off'
        && a.installed_version && a.installed_version === a.latest_version
        && String(a.release_summary || '').toLowerCase().includes('restart');
    });
  const n = Number(entity.state);
  if (Number.isFinite(n) && n === 1) return T('updates.one', '1 Update');
  if (Number.isFinite(n) && n > 1) return T('updates.n', '{n} Updates', { n });
  return restart ? T('updates.restart_required', 'Restart required') : T('updates.up_to_date', 'Up to date');
]]]

state.value:
[[[
  const restart = Object.keys(states)
    .filter(id => id.startsWith('update.'))
    .some(id => {
      const e = states[id], a = (e && e.attributes) || {};
      return e && e.state === 'off'
        && a.installed_version && a.installed_version === a.latest_version
        && String(a.release_summary || '').toLowerCase().includes('restart');
    });
  const n = Number(entity.state);
  return (Number.isFinite(n) && n > 0) || restart;
]]]

hemma_vacuum.state_display:
[[[
  if (!entity?.state) return "";
  if (window.hemmaVacuumWord) return window.hemmaVacuumWord(hass, entity);
  try { return hass.formatEntityState(entity) || entity.state; } catch (e) { return entity.state; }
]]]
